{"command":"mkdir -p /tmp/scratch && cat > /tmp/scratch/genkey.go <<'GO'
package main

import (
 "crypto/ecdh"
 "crypto/rand"
 "fmt"
 "os"
 "strings"
)
const charset="qzpzry9x8gf2tvdw0s3jn54khce6mua7l"
// actually correct charset below
var cs="qpzry9x8gf2tvdw0s3jn54khce6mua7l"
func polymod(values []int) int {
 chk:=1
 for _,v:=range values {
  top:=chk>>25
  chk=(chk&0x1ffffff)<<5 ^ v
  if top&1!=0 {chk^=0x3b6a57b2}
  if top&2!=0 {chk^=0x26508e6d}
  if top&4!=0 {chk^=0x1ea119fa}
  if top&8!=0 {chk^=0x3d4233dd}
  if top&16!=0 {chk^=0x2a1462b3}
 }
 return chk
}
func hrpexpand(hrp string) []int {
 out:=[]int{}
 for _,c:=range hrp {out=append(out,int(c)>>5)}
 out=append(out,0)
 for _,c:=range hrp {out=append(out,int(c)&31)}
 return out
}
func encode(hrp string, data []byte) string {
 // convert bits 8 to 5
 values:=convert(data)
 combined:=append(hrpexpand(hrp), values...)
 combined=append(combined, []int{0,0,0,0,0,0}...)
 pm:=polymod(combined)^1
 var sb strings.Builder
 sb.WriteString(hrp); sb.WriteByte('1')
 for _,v:=range values {sb.WriteByte(cs[v])}
 for i:=0;i<6;i++ {sb.WriteByte(cs[(pm>>uint(5*(5-i)))&31])}
 return sb.String()
}
func convert(data []byte) []int {
 acc:=0; bits:=0; out:=[]int{}
 for _,b:=range data {
  acc=(acc<<8)|int(b); bits+=8
  for bits>=5 {bits-=5; out=append(out,(acc>>uint(bits))&31)}
 }
 if bits>0 {out=append(out,(acc<<uint(5-bits))&31)}
 return out
}
func main(){
 priv,err:=ecdh.X25519().GenerateKey(rand.Reader); if err!=nil{panic(err)}
 fmt.Fprintf(os.Stderr,"priv bytes %x\n", priv.Bytes())
 fmt.Println("# public key: "+encode("age", priv.PublicKey().Bytes()))
 fmt.Println(strings.ToUpper(encode("age-secret-key-", priv.Bytes())))
 _=charset
}
GO
cd /tmp/scratch && go mod init scratch 2>&1; go run genkey.go > key.txt 2>priv.txt; cat key.txt; cat priv.txt"}

