// HKDF-SHA256
func hkdfSHA256(ikm, salt, info []byte, length int) []byte {
	if salt == nil {
		salt = make([]byte, 32)
	}
	mac := hmac.New(sha256.New, salt)
	mac.Write(ikm)
	prk := mac.Sum(nil)
	var okm, t []byte
	for counter := byte(1); len(okm) < length; counter++ {
		m := hmac.New(sha256.New, prk)
		m.Write(t)
		m.Write(info)
		m.Write([]byte{counter})
		t = m.Sum(nil)
		okm = append(okm, t...)
	}
	return okm[:length]
}

func hmacSHA256(key, msg []byte) []byte {
	m := hmac.New(sha256.New, key)
	m.Write(msg)
	return m.Sum(nil)
}

// ChaCha20-Poly1305 (IETF, 12-byte nonce)

func rotl32(v uint32, c int) uint32 { return (v << c) | (v >> (32 - c)) }
func quarterRound(st *[16]uint32, a, b, c, d int) {
	st[a] += st[b]
	st[d] ^= st[a]
	st[d] = rotl32(st[d], 16)
	st[c] += st[d]
	st[b] ^= st[c]
	st[b] = rotl32(st[b], 12)
	st[a] += st[b]
	st[d] ^= st[a]
	st[d] = rotl32(st[d], 8)
	st[c] += st[d]
	st[b] ^= st[c]
	st[b] = rotl32(st[b], 7)
}

func chachaBlock(key []byte, counter uint32, nonce []byte) [64]byte {
	var st [16]uint32
	st[0] = 0x61707865
	st[1] = 0x3320646e
	st[2] = 0x79622d32
	st[3] = 0x6b206574
	for i := 0; i < 8; i++ {
		st[4+i] = binary.LittleEndian.Uint32(key[i*4:])
	}
	st[12] = counter
	for i := 0; i < 3; i++ {
		st[13+i] = binary.LittleEndian.Uint32(nonce[i*4:])
	}
	orig := st
	for i := 0; i < 10; i++ {
		quarterRound(&st, 0, 4, 8, 12)
		quarterRound(&st, 1, 5, 9, 13)
		quarterRound(&st, 2, 6, 10, 14)
		quarterRound(&st, 3, 7, 11, 15)
		quarterRound(&st, 0, 5, 10, 15)
		quarterRound(&st, 1, 6, 11, 12)
		quarterRound(&st, 2, 7, 8, 13)
		quarterRound(&st, 3, 4, 9, 14)
	}
	var out [64]byte
	for i := 0; i < 16; i++ {
		binary.LittleEndian.PutUint32(out[i*4:], st[i]+orig[i])
	}
	return out
}

func chachaXOR(key, nonce []byte, counter uint32, in []byte) []byte {
	out := make([]byte, len(in))
	for i := 0; i < len(in); i += 64 {
		block := chachaBlock(key, counter, nonce)
		counter++
		n := 64
		if len(in)-i < 64 {
			n = len(in) - i
		}
		for j := 0; j < n; j++ {
			out[i+j] = in[i+j] ^ block[j]
		}
	}
	return out
}

var polyP = new(big.Int).Sub(new(big.Int).Lsh(big.NewInt(1), 130), big.NewInt(5))

func poly1305Tag(msg, key []byte) []byte {
	rBytes := make([]byte, 16)
	copy(rBytes, key[:16])
	rBytes[3] &= 15
	rBytes[7] &= 15
	rBytes[11] &= 15
	rBytes[15] &= 15
	rBytes[4] &= 251
	rBytes[8] &= 251
	// Actually clamp as per RFC: r[3],r[7],r[11],r[15] & 15 etc and r[4],r[8],r[12] & 251? Let's use standard masking below via integer:
	// Simpler recompute r by reversing: clamp(r) = r & 0x0ffffffc0ffffffc0ffffffc0fffffff
	// copy original
	copy(rBytes, key[:16])
	// We'll compute integer from little endian and mask.
	rInt := leToBig(rBytes)
	mask, _ := new(big.Int).SetString("0ffffffc0ffffffc0ffffffc0fffffff", 16)
	rInt.And(rInt, mask)
	sInt := leToBig(key[16:32])
	acc := big.NewInt(0)
	for i := 0; i < len(msg); i += 16 {
		end := i + 16
		if end > len(msg) {
			end = len(msg)
		}
		chunk := msg[i:end]
		n := leToBig(chunk)
		n.Add(n, new(big.Int).Lsh(big.NewInt(1), uint(8*len(chunk))))
		acc.Add(acc, n)
		acc.Mul(acc, rInt)
		acc.Mod(acc, polyP)
	}
	acc.Add(acc, sInt)
