	b := acc.Bytes()
	for i := 0; i < len(b); i++ {
		out[i] = b[len(b)-1-i]
	}
	return out
}

func leToBig(b []byte) *big.Int {
	rev := make([]byte, len(b))
	for i, v := range b {
		rev[len(b)-1-i] = v
	}
	return new(big.Int).SetBytes(rev)
}

func pad16(b []byte) []byte {
	if len(b)%16 == 0 {
		return nil
	}
	return make([]byte, 16-len(b)%16)
}

func aeadEncrypt(key, nonce, plaintext, aad []byte) []byte {
	polyKeyBlock := chachaBlock(key, 0, nonce)
	polyKey := polyKeyBlock[:32]
	ct := chachaXOR(key, nonce, 1, plaintext)
	var macData []byte
	macData = append(macData, aad...)
	macData = append(macData, pad16(aad)...)
	macData = append(macData, ct...)
	macData = append(macData, pad16(ct)...)
	var lb [16]byte
	binary.LittleEndian.PutUint64(lb[0:], uint64(len(aad)))
	binary.LittleEndian.PutUint64(lb[8:], uint64(len(ct)))
	macData = append(macData, lb[:]...)
	tag := poly1305Tag(macData, polyKey)
	return append(ct, tag...)
}

func aeadDecrypt(key, nonce, ciphertext, aad []byte) ([]byte, error) {
	if len(ciphertext) < 16 {
		return nil, errors.New("chacha20poly1305: message authentication failed")
	}
	ct := ciphertext[:len(ciphertext)-16]
	tag := ciphertext[len(ciphertext)-16:]
	polyKeyBlock := chachaBlock(key, 0, nonce)
	polyKey := polyKeyBlock[:32]
	var macData []byte
	macData = append(macData, aad...)
	macData = append(macData, pad16(aad)...)
	macData = append(macData, ct...)
	macData = append(macData, pad16(ct)...)
	var lb [16]byte
	binary.LittleEndian.PutUint64(lb[0:], uint64(len(aad)))
	binary.LittleEndian.PutUint64(lb[8:], uint64(len(ct)))
	macData = append(macData, lb[:]...)
	expected := poly1305Tag(macData, polyKey)
	if subtle.ConstantTimeCompare(tag, expected) != 1 {
