	tmp := make([]byte, 128*r)
	copy(tmp, b[:128*r]) // per block handling below: need RO Mix per p block
	// General: for each p block, ROMix
	for i := 0; i < p; i++ {
		block := b[i*128*r : (i+1)*128*r]
		// ROMix(block, n)
		cur := make([]byte, 128*r)
		copy(cur, block)
