			idx := integer(cur, r) & uint64(n-1)
			for k := 0; k < 128*r; k++ {
				cur[k] ^= v[idx][k]
			}
			cur = blockMixSalsa8(cur, r)
		}
		copy(block, cur)
		_ = xy
		_ = tmp
	}
