// newArmorReader expects underlying reader positioned at start; it peeks to decide? Caller decides armor by peeking.
func newArmorReader(r io.Reader) *armorReader {
	var br *bufio.Reader
	if b, ok := r.(*bufio.Reader); ok {
		br = b
	} else {
		br = bufio.NewReader(r)
	}
	return &armorReader{r: br}
