// invalid armor error type plain message
type armorError struct{ msg string }
func (e *armorError) Error() string { return e.msg }
func armorErrf(format string, args ...interface{}) error { return &armorError{msg: fmt.Sprintf(format, args...)} }

// readLine returns a line without trailing \n? It returns raw line string and error.
