func newStreamReader(src *bufio.Reader, fileKey []byte, ar *armorReader) (*streamReader, error) {
	nonce := make([]byte, 16)
	if _, err := io.ReadFull(src, nonce); err != nil {
		if err == io.EOF || err == io.ErrUnexpectedEOF {
