	return &streamReader{src: src, key: key, armor: ar}, nil
}
func (r *streamReader) fill() error {
	if r.done { return io.EOF }
	buf := make([]byte, 65536+16)
	n, err := io.ReadFull(r.src, buf)
	var final bool
	if err == nil {
		// full chunk, check if more data exists
		_, perr := r.src.Peek(1)
		if perr == io.EOF {
			final = true
		} else if perr != nil {
			// armor errors etc propagate
			if perr != bufio.ErrBufferFull {
				return perr
			}
			final = false
		} else {
			final = false
		}
	} else if err == io.ErrUnexpectedEOF {
		final = true
		if n == 0 {
			r.done = true
			return fmt.Errorf("failed to decrypt and authenticate payload chunk, file may be corrupted or tampered with")
		}
	} else if err == io.EOF {
		// No chunk where one required
		return fmt.Errorf("failed to decrypt and authenticate payload chunk, file may be corrupted or tampered with")
	} else {
		return err
	}
	ct := buf[:n]
	var nonce [12]byte
	c := r.counter
	for i := 10; i >= 0; i-- { nonce[i] = byte(c); c >>= 8 }
	if final { nonce[11] = 1 }
	pt, derr := aeadDecrypt(r.key, nonce[:], ct, nil)
	if derr != nil {
		return fmt.Errorf("failed to decrypt and authenticate payload chunk, file may be corrupted or tampered with")
	}
	r.buf = pt
	r.off = 0
	r.counter++
	if final { r.final = true }
	return nil
}
func (r *streamReader) Read(p []byte) (int, error) {
	if r.err != nil { return 0, r.err }
	for r.off >= len(r.buf) {
		if r.final {
			r.done = true
			return 0, io.EOF
		}
		if err := r.fill(); err != nil {
			if err == io.EOF { r.done = true; return 0, io.EOF }
			r.err = err
			return 0, err
		}
		if len(r.buf) == 0 && r.final {
			// empty final chunk: loop will return EOF next
			continue
		}
	}
	n := copy(p, r.buf[r.off:])
	r.off += n
	return n, nil
}

