package main

import (
	"fmt"
	"os"
	"strings"
	"syscall"
	"unsafe"
)

type termios struct {
	Iflag  uint32
	Oflag  uint32
	Cflag  uint32
	Lflag  uint32
	Line   byte
	Cc     [32]byte
	Ispeed uint32
	Ospeed uint32
}

const ioctlReadTermios = 0x5401 // TCGETS linux
const ioctlWriteTermios = 0x5402 // TCSETS

func ioctlTermios(fd uintptr, req uintptr, term *termios) error {
	_, _, errno := syscall.Syscall(syscall.SYS_IOCTL, fd, req, uintptr(unsafe.Pointer(term)))
	if errno != 0 { return errno }
	return nil
}
func isTerminalFd(fd uintptr) bool {
	var t termios
	return ioctlTermios(fd, ioctlReadTermios, &t) == nil
}
func getTermios(fd uintptr) (*termios, error) {
	var t termios
	err := ioctlTermios(fd, ioctlReadTermios, &t)
	return &t, err
}
func setTermios(fd uintptr, t *termios) error { return ioctlTermios(fd, ioctlWriteTermios, t) }

// terminalFile returns a file to read prompts from (and write prompts to).
// If stdin is a terminal, use os.Stdin. Else open /dev/tty.
func terminalFile() (*os.File, bool, error) {
	if isTerminalFd(os.Stdin.Fd()) {
		return os.Stdin, false, nil
	}
	f, err := os.OpenFile("/dev/tty", os.O_RDWR, 0)
	if err != nil {
		return nil, false, fmt.Errorf("standard input is not a terminal, and /dev/tty is not available: %w", err)
	}
	return f, true, nil
}

// readPasswordFromTTY reads a line with echo disabled. Prompt is written, and after reading
// "\r\n\x1b[F\x1b[K" is written (matching observed behavior).
func readPasswordFromTTY(tty *os.File, prompt string) (string, error) {
	fd := tty.Fd()
	old, err := getTermios(fd)
	if err != nil {
		return "", err
	}
	newState := *old
	// Disable echo, canonical mode, signals like x/term ReadPassword-ish but keep ability to read newline.
	newState.Lflag &^= 0x0008 // ECHO (linux 8)
	newState.Lflag &^= 0x0002 // ICANON
	newState.Lflag &^= 0x0001 // ISIG? Actually ISIG is 1 on linux
	// VMIN=6? cc indices: VMIN is 6 on linux, VTIME 5
	newState.Cc[6] = 1
	newState.Cc[5] = 0
	if _, err := tty.WriteString(prompt); err != nil {
		return "", err
	}
	if err := setTermios(fd, &newState); err != nil {
		return "", err
	}
	var buf []byte
	one := make([]byte, 1)
	var readErr error
	for {
		n, err := tty.Read(one)
		if n > 0 {
			c := one[0]
			if c == '\n' || c == '\r' {
				break
			}
			buf = append(buf, c)
		}
		if err != nil {
			readErr = err
			break
		}
		if n == 0 {
			break
		}
	}
	// restore before writing newline/escapes (original writes after restore? Our output sequence regardless driver: writing escapes while raw would be same chars)
	setTermios(fd, old)
	if _, err := tty.WriteString("\r\n\x1b[F\x1b[K"); err != nil && readErr == nil {
		readErr = err
	}
	if readErr != nil {
		return "", readErr
	}
	return string(buf), nil
}

// readValueFromTTY is generalized prompt used for plugin secret prompts (password-like)
func readSecretValue(prompt string) (string, error) {
	tty, shouldClose, err := terminalFile()
	if err != nil { return "", err }
	if shouldClose { defer tty.Close() }
	return readPasswordFromTTY(tty, prompt)
}

// readSingleSelection reads one rune for confirm, clearing prompt line after.
// It returns the rune read as string (single character), or error.
func readSelectionValue(prompt string) (string, error) {
	tty, shouldClose, err := terminalFile()
	if err != nil { return "", err }
	if shouldClose { defer tty.Close() }
	fd := tty.Fd()
	old, err := getTermios(fd)
	if err != nil { return "", err }
	newState := *old
	newState.Lflag &^= 0x0008
	newState.Lflag &^= 0x0002
	newState.Lflag &^= 0x0001
	newState.Cc[6] = 1
	newState.Cc[5] = 0
	if _, err := tty.WriteString(prompt); err != nil { return "", err }
	if err := setTermios(fd, &newState); err != nil { return "", err }
	// Read a single UTF-8 rune
	buf := make([]byte, 0, 4)
	one := make([]byte, 1)
	var readErr error
	for {
		n, err := tty.Read(one)
		if n > 0 {
			buf = append(buf, one[0])
			// Determine if rune complete: try decode
			r := []rune(string(buf))
			if len(r) == 1 && string(r) != "\ufffd" {
				break
			}
			if len(buf) >= 4 { break }
			continue
		}
		if err != nil { readErr = err; break }
		if n == 0 { break }
	}
	setTermios(fd, old)
	if _, err := tty.WriteString("\r\n\x1b[F\x1b[K"); err != nil && readErr == nil { readErr = err }
	if readErr != nil { return "", readErr }
	return string(buf), nil
}

func writeToTTY(s string) {
	tty, shouldClose, err := terminalFile()
	if err != nil {
		// Fallback to stderr? Original autogenerated passphrase message goes to terminal; if no tty, this path wouldn't happen because passphrase read already failed.
		fmt.Fprint(os.Stderr, s)
		return
	}
	if shouldClose { defer tty.Close() }
	fmt.Fprint(tty, s)
}

