{"command":"cat > /workspace/ssh.go <<'EOF'
package main

import (
	"bytes"
	"crypto"
	"crypto/ed25519"
	"crypto/rand"
	"crypto/rsa"
	"crypto/sha256"
	"crypto/x509"
	"encoding/base64"
	"encoding/binary"
	"encoding/pem"
	"errors"
	"fmt"
	"math/big"
	"strings"
)

// SSH wire helpers
type sshBuf struct { b []byte; err error }
func (s *sshBuf) writeString(v []byte) {
	var l [4]byte; binary.BigEndian.PutUint32(l[:], uint32(len(v))); s.b = append(s.b, l[:]...); s.b = append(s.b, v...)
}
func (s *sshBuf) writeUint32(v uint32) { var l [4]byte; binary.BigEndian.PutUint32(l[:], v); s.b = append(s.b, l[:]...) }
func (s *sshBuf) writeMPInt(v *big.Int) {
	if v.Sign() == 0 { s.writeString(nil); return }
	b := v.Bytes()
	if b[0]&0x80 != 0 { b = append([]byte{0}, b...) }
	s.writeString(b)
}
type sshReader struct { b []byte; off int; err error }
func (r *sshReader) readString() []byte {
	if r.err != nil { return nil }
	if len(r.b)-r.off < 4 { r.err = fmt.Errorf("ssh: short read"); return nil }
	l := int(binary.BigEndian.Uint32(r.b[r.off:])); r.off += 4
	if l < 0 || len(r.b)-r.off < l { r.err = fmt.Errorf("ssh: short read"); return nil }
	v := r.b[r.off:r.off+l]; r.off += l; return v
}
func (r *sshReader) readUint32() uint32 {
	if r.err != nil { return 0 }
	if len(r.b)-r.off < 4 { r.err = fmt.Errorf("ssh: short read"); return 0 }
	v := binary.BigEndian.Uint32(r.b[r.off:]); r.off += 4; return v
}
func (r *sshReader) readMPInt() *big.Int {
	b := r.readString(); if r.err != nil { return nil }
	return new(big.Int).SetBytes(b)
}
func (r *sshReader) remaining() int { return len(r.b)-r.off }

func sshMarshalPKCS1Public(n *big.Int, e int) []byte { _ = n; _ = e; return nil }

// Marshal authorized public key blob for RSA/Ed
func sshBlobRSA(pub *rsa.PublicKey) []byte {
	var buf sshBuf; buf.writeString([]byte("ssh-rsa")); buf.writeMPInt(big.NewInt(int64(pub.E))); buf.writeMPInt(pub.N); return buf.b
}
func sshBlobEd(pub ed25519.PublicKey) []byte {
	var buf sshBuf; buf.writeString([]byte("ssh-ed25519")); buf.writeString([]byte(pub)); return buf.b
}
func sshTag(blob []byte) []byte { h := sha256.Sum256(blob); return h[:4] }

// Parse public key blob, returning kind and key.
type sshPublic struct {
	Kind string // ssh-rsa, ssh-ed25519, or wire type for unsupported
	RSA *rsa.PublicKey
	Ed ed25519.PublicKey
	Blob []byte
	TypeName string
}
func parseSSHPublicBlob(blob []byte) (*sshPublic, error) {
	r := &sshReader{b: blob}
	typ := string(r.readString())
	if r.err != nil { return nil, r.err }
	sp := &sshPublic{Blob: append([]byte{}, blob...), TypeName: typ, Kind: typ}
	switch typ {
	case "ssh-rsa":
		eBig := r.readMPInt(); if r.err != nil { return nil, r.err }
		nBig := r.readMPInt(); if r.err != nil { return nil, r.err }
		if r.remaining() > 0 { return nil, fmt.Errorf("ssh: trailing junk in public key") }
		if !eBig.IsInt64() || eBig.Int64() > 0x7fffffff { return nil, fmt.Errorf("ssh: exponent out of range") }
		sp.RSA = &rsa.PublicKey{N: nBig, E: int(eBig.Int64())}
	case "ssh-ed25519":
		pk := r.readString(); if r.err != nil { return nil, r.err }
		if len(pk) != 32 { return nil, fmt.Errorf("invalid size %d for Ed25519 public key", len(pk)) }
		if r.remaining() > 0 { return nil, fmt.Errorf("ssh: trailing junk in public key") }
		sp.Ed = append(ed25519.PublicKey{}, pk...)
	case "ssh-dss":
		// p,q,g,y
		vals := make([]*big.Int,4)
		for i:=0;i<4;i++ { vals[i]=r.readMPInt(); if r.err != nil { return nil, r.err } }
		if vals[0].BitLen() < 1024 { // Go ssh checks DSA params? Approx observed "unsupported DSA key size 1" for p=1
			return nil, fmt.Errorf("ssh: unsupported DSA key size %d", vals[0].Int64())
		}
		if r.remaining()>0 { return nil, fmt.Errorf("ssh: trailing junk in public key") }
	default:
		// check known algorithms list from x/crypto/ssh
		if !isKnownSSHAlgo(typ) {
			return nil, fmt.Errorf("ssh: unknown key algorithm: %s", typ)
		}
		// For known unsupported types (ecdsa, sk, certs), parsing may succeed in Go; we approximate by accepting generic and storing type.
		// Try to consume remaining strings generically? If remaining is malformed, short read etc.
		// For ecdsa, format is curve string + point string.
		if strings.HasPrefix(typ, "ecdsa-") {
			_ = r.readString(); _ = r.readString(); if r.err != nil { return nil, r.err }
			if r.remaining()>0 { return nil, fmt.Errorf("ssh: trailing junk in public key") }
		}
		// other types: accept as opaque (may be cert etc.) – callers treat as unsupported.
	}
	return sp, nil
}

func isKnownSSHAlgo(t string) bool {
	switch t {
	case "ssh-rsa","ssh-dss","ssh-ed25519","ecdsa-sha2-nistp256","ecdsa-sha2-nistp384","ecdsa-sha2-nistp521",
		"ssh-rsa-cert-v01@openssh.com","ssh-dss-cert-v01@openssh.com","ssh-ed25519-cert-v01@openssh.com",
		"ecdsa-sha2-nistp256-cert-v01@openssh.com","ecdsa-sha2-nistp384-cert-v01@openssh.com","ecdsa-sha2-nistp521-cert-v01@openssh.com",
		"sk-ssh-ed25519@openssh.com","sk-ecdsa-sha2-nistp256@openssh.com","sk-ssh-ed25519-cert-v01@openssh.com","sk-ecdsa-sha2-nistp256-cert-v01@openssh.com",
		"rsa-sha2-256","rsa-sha2-512","rsa-sha2-256-cert-v01@openssh.com","rsa-sha2-512-cert-v01@openssh.com":
		return true
	}
	return false
}

// Parse authorized key text (single line or multi). Returns public or error matching ssh.ParseAuthorizedKey-style messages.
func parseSSHAuthorizedKey(in []byte) (*sshPublic, error) {
	var lastErr error
	haveIgnored := false
	// Split lines
	for len(in) > 0 {
		var line []byte
		if idx := bytes.IndexByte(in, '\n'); idx >= 0 {
			line = in[:idx]; in = in[idx+1:]
		} else {
			line = in; in = nil
		}
		line = bytes.TrimSuffix(line, []byte("\r"))
		if len(bytes.TrimSpace(line)) == 0 { continue }
		if bytes.HasPrefix(bytes.TrimSpace(line), []byte("#")) { continue }
		fields := strings.Fields(string(line))
		if len(fields) < 2 {
			continue
		}
		// fields[1] is assumed encoded key (age only uses simple authorized keys). Options handling approximated: if fields[1] is a known algo and fields length >=3, shift.
		b64field := fields[1]
		if isKnownSSHAlgo(fields[1]) && len(fields) >= 3 {
			b64field = fields[2]
		}
		raw, err := base64.StdEncoding.DecodeString(b64field)
		if err != nil { lastErr = err; haveIgnored = true; continue }
		pub, err := parseSSHPublicBlob(raw)
		if err != nil { lastErr = err; haveIgnored = true; continue }
		return pub, nil
	}
	if haveIgnored && lastErr != nil {
		return nil, fmt.Errorf("ssh: no key found; last parsing error for ignored line: %v", lastErr)
	}
	return nil, fmt.Errorf("ssh: no key found")
}

// ===== SSH recipients =====
type sshRSARecipient struct { pub *rsa.PublicKey; blob []byte }
func (r *sshRSARecipient) wrap(fileKey []byte) (*stanza, []string, error) {
	tag := sshTag(r.blob)
	ct, err := rsa.EncryptOAEP(sha256.New(), rand.Reader, r.pub, fileKey, []byte("age-encryption.org/v1/ssh-rsa"))
	if err != nil { return nil, nil, err }
	return &stanza{Type: "ssh-rsa", Args: []string{b64Encode(tag)}, Body: ct}, nil, nil
}

type sshRSAIdentity struct { priv *rsa.PrivateKey; blob []byte }
func (i *sshRSAIdentity) publicBlob() []byte { if i.blob != nil { return i.blob }; return sshBlobRSA(&i.priv.PublicKey) }
func (i *sshRSAIdentity) unwrap(stanzas []*stanza) ([]byte, error) {
	myTag := b64Encode(sshTag(i.publicBlob()))
	for _, s := range stanzas {
		if s.Type != "ssh-rsa" { continue }
		if len(s.Args) != 1 { return nil, fmt.Errorf("invalid ssh-rsa recipient block") }
		if s.Args[0] != myTag { continue }
		fk, err := rsa.DecryptOAEP(sha256.New(), rand.Reader, i.priv, s.Body, []byte("age-encryption.org/v1/ssh-rsa"))
		if err != nil { return nil, fmt.Errorf("failed to decrypt file key: %w", err) }
		if len(fk) != 16 { return nil, fmt.Errorf("invalid ssh-rsa recipient block: incorrect file key size") }
		return fk, nil
	}
	return nil, errNoMatch
}

// parse SSH private key contents. Returns an identity, or for encrypted keys a lazy identity factory handled by caller.
func parseSSHPrivateKey(contents []byte, passphrase []byte, hasPass bool) (interface{}, error) {
	// returns either *sshRSAIdentity,*sshEdIdentity, *encryptedSSHKey (if encrypted and no pass), or error
	block, _ := pem.Decode(contents)
	if block == nil {
		return nil, fmt.Errorf("ssh: no key found")
	}
	// Encrypted traditional PEM?
	if x509.IsEncryptedPEMBlock(block) {
		if !hasPass {
			// caller will handle via encrypted path
			return &encryptedPEMBlock{block: block}, nil
		}
		der, err := x509.DecryptPEMBlock(block, passphrase)
		if err != nil { return nil, err }
		// try parse as PKCS1/EC/PKCS8 based type?
		return parseDERPrivateKey(block.Type, der)
	}
	switch block.Type {
	case "OPENSSH PRIVATE KEY":
		return parseOpenSSHPrivateKey(block.Bytes, passphrase, hasPass)
	case "RSA PRIVATE KEY":
		k, err := x509.ParsePKCS1PrivateKey(block.Bytes)
		if err != nil { return nil, err }
		return &sshRSAIdentity{priv: k}, nil
	case "EC PRIVATE KEY":
		k, err := x509.ParseECPrivateKey(block.Bytes)
		if err != nil { return nil, err }
		return nil, fmt.Errorf("unsupported SSH identity type: *ecdsa.PrivateKey")
		_ = k
	case "DSA PRIVATE KEY":
		return nil, fmt.Errorf("ssh: unsupported key type %q", block.Type) // approximation
	case "PRIVATE KEY":
		k, err := x509.ParsePKCS8PrivateKey(block.Bytes)
		if err != nil { return nil, err }
		return identityFromGoKey(k)
	case "ENCRYPTED PRIVATE KEY":
		if !hasPass { return &encryptedPEMBlock{block: block}, nil }
		return nil, fmt.Errorf("ssh: cannot decode encrypted private keys")
	default:
		return nil, fmt.Errorf("ssh: unsupported key type %q", block.Type)
	}
}

type encryptedPEMBlock struct{ block *pem.Block }

func parseDERPrivateKey(typ string, der []byte) (interface{}, error) {
	if strings.Contains(typ, "RSA") {
		k, err := x509.ParsePKCS1PrivateKey(der); if err != nil { return nil, err }; return &sshRSAIdentity{priv:k}, nil
	}
	if strings.Contains(typ, "EC") {
		_, err := x509.ParseECPrivateKey(der); if err != nil { return nil, err }; return nil, fmt.Errorf("unsupported SSH identity type: *ecdsa.PrivateKey")
	}
	k, err := x509.ParsePKCS8PrivateKey(der); if err != nil { return nil, err }; return identityFromGoKey(k)
}

func identityFromGoKey(k interface{}) (interface{}, error) {
	switch kk := k.(type) {
	case *rsa.PrivateKey: return &sshRSAIdentity{priv: kk}, nil
	case ed25519.PrivateKey: return &sshEdIdentity{priv: kk}, nil
	case *crypto.PrivateKey: _ = kk; fallthrough
	default:
		// Go type string formatting similar to *ecdsa.PrivateKey
		return nil, fmt.Errorf("unsupported SSH identity type: %T", k)
	}
}

type opensshEncrypted struct {
	cipherName string
	kdfName string
	kdfOpts []byte
	pubBlob []byte
	ciphertext []byte
	comment string
	keyType string
}
type opensshKeyParsed struct {
	identity interface{} // sshRSAIdentity / sshEdIdentity / unsupported error
	encrypted *opensshEncrypted
	pubKey *sshPublic
}

func parseOpenSSHPrivateKey(der []byte, passphrase []byte, hasPass bool) (interface{}, error) {
	parsed, err := parseOpenSSH(der, passphrase, hasPass)
	if err != nil { return nil, err }
	if parsed.encrypted != nil { return parsed, nil } // caller checks type
	return parsed.identity, nil
}

func parseOpenSSH(der []byte, passphrase []byte, hasPass bool) (*opensshKeyParsed, error) {
	const magic = "openssh-key-v1\x00"
	if !bytes.HasPrefix(der, []byte(magic)) { return nil, fmt.Errorf("ssh: unsupported cipher") } // approximation
	rest := der[len(magic):]
	r := &sshReader{b: rest}
	cipherName := string(r.readString()); kdfName := string(r.readString()); kdfOpts := r.readString(); if r.err != nil { return nil, r.err }
	nkeys := int(r.readUint32()); if r.err != nil { return nil, r.err }
	var pubs [][]byte
	for i:=0;i<nkeys;i++ { pb := r.readString(); if r.err != nil { return nil, r.err }; pubs = append(pubs, append([]byte{}, pb...)) }
	encBlock := r.readString(); if r.err != nil { return nil, r.err }
	result := &opensshKeyParsed{}
	if len(pubs)>0 {
		if sp, err := parseSSHPublicBlob(pubs[0]); err == nil { result.pubKey = sp }
	}
	if cipherName != "none" {
		if !hasPass {
			result.encrypted = &opensshEncrypted{cipherName: cipherName, kdfName: kdfName, kdfOpts: append([]byte{}, kdfOpts...), pubBlob: nil, ciphertext: append([]byte{}, encBlock...)}
			if len(pubs)>0 { result.encrypted.pubBlob = pubs[0] }
			return result, nil
		}
		// decrypt
		plain, err := decryptOpenSSHBlock(cipherName, kdfName, kdfOpts, encBlock, passphrase)
		if err != nil { return nil, err }
		return parseOpenSSHPlainBlock(plain, result)
	}
	if kdfName != "none" { return nil, fmt.Errorf("ssh: unknown KDF %q, but cipher is none", kdfName) } // approximate message, rare
	return parseOpenSSHPlainBlock(encBlock, result)
}

func parseOpenSSHPlainBlock(block []byte, result *opensshKeyParsed) (*opensshKeyParsed, error) {
	r := &sshReader{b: block}
	c1 := r.readUint32(); c2 := r.readUint32(); if r.err != nil { return nil, r.err }
	if c1 != c2 { return nil, fmt.Errorf("ssh: checkint mismatch") } // approximate
	keyType := string(r.readString()); if r.err != nil { return nil, r.err }
	switch keyType {
	case "ssh-ed25519":
		pub := r.readString(); priv := r.readString(); _ = r.readString() // comment
		if r.err != nil { return nil, r.err }
		if len(pub)!=32 { return nil, fmt.Errorf("ssh: invalid size for Ed25519 public key?") }
		if len(priv)!=64 { return nil, fmt.Errorf("ssh: invalid size for Ed25519 private key?") }
		privKey := ed25519.PrivateKey(append([]byte{}, priv...))
		result.identity = &sshEdIdentity{priv: privKey}
	case "ssh-rsa":
		n := r.readMPInt(); e := r.readMPInt(); d := r.readMPInt(); iqmp := r.readMPInt(); p := r.readMPInt(); q := r.readMPInt(); _ = r.readString()
		if r.err != nil { return nil, r.err }
		priv := &rsa.PrivateKey{ PublicKey: rsa.PublicKey{N: n, E: int(e.Int64())}, D: d, Primes: []*big.Int{p,q} }
		// precompute using std - Go's priv.Precompute may fill CRT Values with iqmp
		priv.Precompute()
		// Ensure Dp/Dq/Qinv computed; Precompute does if primes
		result.identity = &sshRSAIdentity{priv: priv}
		_ = iqmp
	default:
		// Determine Go type names for some unsupported types
		if strings.HasPrefix(keyType, "ecdsa-") {
			return nil, fmt.Errorf("unsupported SSH identity type: *ecdsa.PrivateKey")
		}
		if keyType == "ssh-dss" {
			return nil, fmt.Errorf("unsupported SSH identity type: *dsa.PrivateKey")
		}
		return nil, fmt.Errorf("ssh: unknown key type %q", keyType) // approximate
	}
	// verify padding
	// remaining bytes should be 1,2,3... padding; Go checks.
	for i, b := range r.b[r.off:] {
		if int(b) != i+1 {
			return nil, fmt.Errorf("ssh: invalid padding in private key")
		}
	}
	return result, nil
}

func decryptOpenSSHBlock(cipherName, kdfName string, kdfOpts, encBlock, passphrase []byte) ([]byte, error) {
	// Supported: aes256-ctr + bcrypt, aes256-cbc + bcrypt, aes128... Might be implemented in bcrypt.go.
	return decryptOpenSSH(cipherName, kdfName, kdfOpts, encBlock, passphrase)
}

