	default:
		// check known algorithms list from x/crypto/ssh
		if !isKnownSSHAlgo(typ) {
			return nil, fmt.Errorf("ssh: unknown key algorithm: %s", typ)
		}
		// For known unsupported types (ecdsa, sk, certs), parsing may succeed in Go; we approximate by accepting generic and storing type.
		// Try to consume remaining strings generically? If remaining is malformed, short read etc.
