}

// recipients-file parsing
func parseRecipientsFile(name string, inputIsStdin bool, tracker *stdinTracker, logWarn func(string, ...interface{})) ([]recipient, error) {
	var r io.Reader
	if name == "-" {
		if inputIsStdin || (tracker != nil && tracker.used) {
			return nil, fmt.Errorf("failed to parse recipient file %q: standard input is used for multiple purposes", name)
