			return nil, fmt.Errorf("unknown recipient type: %q", s)
		}
	default:
		return nil, fmt.Errorf("unknown recipient type: %q", s)
	}
}

// bech32DecodeAnyCheck decodes expecting exactly hrp, but errors returned as raw bech32 errors (not hrp mismatch formatted)
func bech32DecodeAnyCheck(expected, s string) (string, []byte, error) {
	hrp, data, err := bech32DecodeAny(s)
	if err != nil { return "", nil, err }
	if hrp != expected {
		// This case is unlikely due prefix checks; treat as invalid checksum ??? Use bech32 decode with expected for error fidelity.
		_, err2 := bech32Decode(expected, s)
		if err2 != nil { return "", nil, err2 }
		return hrp, data, nil
	}
	return hrp, data, nil
}

// Parse identity string (one line)
func parseIdentity(s string) (identity, error) {
	switch {
	case strings.HasPrefix(s, "AGE-SECRET-KEY-PQ-1"):
		data, err := bech32Decode("age-secret-key-pq-", strings.ToLower(s))
		// Original expects uppercase input prefix but bech32 decode is on original for mixed case detection:
		// To preserve mixed case error, decode on original if case not all upper/lower coherent... Our prefix is uppercase; decode using lowercase HRP check after lowering loses mixed detection.
		// Re-run with validation:
		if derr := checkBech32CaseError(s); derr != nil { return nil, fmt.Errorf("malformed secret key: %w", derr) }
		if err != nil { return nil, fmt.Errorf("malformed secret key: %w", err) }
		if len(data) != 32 { return nil, fmt.Errorf("malformed secret key: invalid MLKEM768-X25519 secret key") }
		return &pqIdentity{seed: data}, nil
	case strings.HasPrefix(s, "AGE-SECRET-KEY-1"):
		if derr := checkBech32CaseError(s); derr != nil { return nil, fmt.Errorf("malformed secret key: %w", derr) }
		data, err := bech32DecodeForIdentity("age-secret-key-", s)
		if err != nil { return nil, fmt.Errorf("malformed secret key: %w", err) }
		if len(data) != 32 { return nil, fmt.Errorf("malformed secret key: invalid X25519 secret key") }
		return &x25519Identity{secret: data}, nil
	case strings.HasPrefix(s, "AGE-PLUGIN-"):
		// decode any bech32, hrp should be age-plugin-<name>-
		hrp, data, err := bech32DecodeAny(s)
		if err != nil { return nil, fmt.Errorf("invalid identity encoding: %w", err) }
		if !strings.HasPrefix(hrp, "age-plugin-") || !strings.HasSuffix(hrp, "-") {
			return nil, fmt.Errorf("invalid identity encoding: invalid plugin identity")
		}
		name := strings.TrimSuffix(strings.TrimPrefix(hrp, "age-plugin-"), "-")
		if name == "" { return nil, fmt.Errorf("invalid identity encoding: invalid plugin name") }
		_ = data
		return newPluginIdentityFromString(name, s), nil
	case strings.HasPrefix(s, "age1"):
		return nil, fmt.Errorf("apparent recipient found in identities file")
	default:
		return nil, fmt.Errorf("unknown identity type")
	}
}

func checkBech32CaseError(s string) error {
	hasLower, hasUpper := false, false
	for i:=0;i<len(s);i++ {
		if s[i]>='a' && s[i]<='z' { hasLower=true }
		if s[i]>='A' && s[i]<='Z' { hasUpper=true }
	}
	if hasLower && hasUpper { return fmt.Errorf("mixed case") }
	return nil
}

// decode identity bech32 where input is uppercase; our bech32Decode expects lowercase hrp but handles case via lowering internally for checksum etc.
// It already lowercases internally, but it checks mixed case first.
func bech32DecodeForIdentity(expected, s string) ([]byte, error) {
	return bech32Decode(expected, s)
}

// stdin tracking
type stdinTracker struct { used bool; usedFor string }
func (t *stdinTracker) claim(what string) error {
	if t.used { return fmt.Errorf("standard input is used for multiple purposes") }
	t.used = true; t.usedFor = what; return nil
}

// recipients-file parsing
func parseRecipientsFile(name string, inputIsStdin bool, tracker *stdinTracker, logWarn func(string, ...interface{})) ([]recipient, error) {
	var r io.Reader
	if name == "-" {
		if inputIsStdin || (tracker != nil && tracker.used) {
			return nil, fmt.Errorf("failed to parse recipient file %q: standard input is used for multiple purposes", name)
		}
		if tracker != nil { tracker.used = true; tracker.usedFor = "recipients" }
		r = os.Stdin
	} else {
		f, err := os.Open(name)
		if err != nil {
			return nil, fmt.Errorf("failed to parse recipient file %q: failed to open recipient file: %w", name, err)
		}
		defer f.Close()
		r = f
		return parseRecipients(r, name, logWarn)
	}
	recips, err := parseRecipients(r, name, logWarn)
	if err != nil {
		// parseRecipients already includes quoting etc; wrap with file prefix as original does for non-open errors
		// parseRecipients returns errors formatted as "\"name\": ..." or "\"name\": failed..."
		// CLI outer wraps as failed to parse recipient file %q: %w ; we need do that here for consistency with expected output.
		// But we already handled open case with full wrapping. For stdin and regular parsed errors, original output is: failed to parse recipient file "x": "x": malformed...
		// So wrap here:
		return nil, fmt.Errorf("failed to parse recipient file %q: %w", name, err)
	}
	return recips, nil
}

// parseRecipients reads from r, returns errors whose message starts with %q filename
func parseRecipients(r io.Reader, name string, logWarn func(string, ...interface{})) ([]recipient, error) {
	scanner := bufio.NewScanner(r)
	var recips []recipient
	lineNum := 0
	for scanner.Scan() {
		lineNum++
		line := scanner.Text()
		if line == "" || strings.HasPrefix(line, "#") { continue }
		if len(line) > 8192 {
			return nil, fmt.Errorf("%q: line %d is too long", name, lineNum)
		}
		rec, err := parseRecipient(line)
		if err != nil {
			// try SSH fallback for unsupported keys
			if pub, serr := parseSSHAuthorizedKey([]byte(line)); serr == nil {
				if logWarn != nil { logWarn("recipients file %q: ignoring unsupported SSH key of type %q at line %d", name, pub.TypeName, lineNum) }
				continue
			}
			return nil, fmt.Errorf("%q: malformed recipient at line %d", name, lineNum)
		}
		recips = append(recips, rec)
	}
	if err := scanner.Err(); err != nil {
		return nil, fmt.Errorf("%q: failed to read recipients file: %w", name, err)
	}
	if len(recips)==0 {
		return nil, fmt.Errorf("%q: no recipients found", name)
	}
	return recips, nil
}

// identities file parsing (contents already read). This handles SSH PEM detection and line parsing.
func parseIdentitiesFromBytes(contents []byte, name string) ([]identity, error) {
	if bytesHasPrefix(contents, []byte("-----BEGIN")) {
		id, err := parseSSHIdentityFile(contents, name, nil, false)
		if err != nil {
			return nil, fmt.Errorf("failed to read %q: %w", name, err) // caller will add reading prefix? We design callers to handle.
		}
		return id, nil
	}
	ids, err := parseIdentityLines(contents)
	if err != nil {
		return nil, err
	}
	return ids, nil
}

func bytesHasPrefix(b, prefix []byte) bool { return len(b)>=len(prefix) && string(b[:len(prefix)])==string(prefix) }

// parseIdentityLines scans lines (bufio.Scanner default limits)
func parseIdentityLines(contents []byte) ([]identity, error) {
	scanner := bufio.NewScanner(bytesReader(contents))
	var ids []identity
	lineNum := 0
	for scanner.Scan() {
		lineNum++
		line := scanner.Text()
		if line == "" || strings.HasPrefix(line, "#") { continue }
		id, err := parseIdentity(line)
		if err != nil {
			return nil, fmt.Errorf("error at line %d: %w", lineNum, err)
		}
		ids = append(ids, id)
	}
	if err := scanner.Err(); err != nil {
		return nil, fmt.Errorf("failed to read identities file: %w", err)
	}
	if len(ids)==0 { return nil, fmt.Errorf("no identities found") }
	return ids, nil
}

func bytesReader(b []byte) io.Reader { return strings.NewReader(string(b)) }
