package main

import (
	"crypto/ecdh"
	"fmt"
)

func p256CompressedToUncompressed(c []byte) ([]byte, error) {
	if len(c)!=33 { return nil, fmt.Errorf("invalid P256 point encoding") }
	// Go 1.21 ecdh P256 does not support compressed; use crypto/elliptic
	return uncompressP256(c)
}
func p256UncompressedValidate(u []byte) ([]byte, error) {
	if len(u)!=65 || u[0]!=4 { return nil, fmt.Errorf("crypto/ecdh: invalid public key") }
	if _, err := ecdh.P256().NewPublicKey(u); err != nil { return nil, err }
	return u, nil
}
