package main

import (
	"crypto/elliptic"
	"fmt"
	"math/big"
)

func uncompressP256(c []byte) ([]byte, error) {
	if len(c)!=33 || (c[0]!=2 && c[0]!=3) { return nil, fmt.Errorf("invalid P256 point encoding") }
	x := new(big.Int).SetBytes(c[1:])
	y := elliptic.P256().UnmarshalCompressed(append(append([]byte{}, c...)[:], []byte{}...)) // placeholder will replace below
	_ = x; _ = y
	// Use stdlib UnmarshalCompressed properly:
	xx, yy := elliptic.P256().UnmarshalCompressed(c)
	if xx == nil { return nil, fmt.Errorf("invalid P256 point encoding") }
	out := make([]byte,65); out[0]=4
	xb := xx.Bytes(); copy(out[1+32-len(xb):33], xb)
	yb := yy.Bytes(); copy(out[33+32-len(yb):65], yb)
	return out, nil
}
