cat > /workspace/plugin.go <<'EOF'
package main

import (
	"bufio"
	"fmt"
	"io"
	"os"
	"os/exec"
	"strconv"
	"strings"
)

// Plugin recipient / identity client implementation (age plugin protocol v1)

// pluginClient manages a single plugin process for one recipient/identity instance.
type pluginClient struct {
	name string
	cmd *exec.Cmd
	stdin io.WriteCloser
	stdout *bufio.Reader
	stderr io.Writer // inherited
	started bool
	ui *pluginUI
	// stanza read state
}

func pluginNotFoundError(name string) error {
	// Exec lookpath error mimics Go: exec: "age-plugin-foo": executable file not found in $PATH
	return fmt.Errorf("couldn't start plugin: %q plugin not found: exec: %q: executable file not found in $PATH", name, "age-plugin-"+name)
}

func (c *pluginClient) start(phase string) error {
	if c.started { return nil }
	path, err := exec.LookPath("age-plugin-" + c.name)
	if err != nil {
		return pluginNotFoundError(c.name)
	}
	_ = path
	cmd := exec.Command("age-plugin-"+c.name, "--age-plugin="+phase)
	cmd.Stderr = os.Stderr
	stdin, err := cmd.StdinPipe(); if err != nil { return fmt.Errorf("couldn't start plugin: %w", err) }
	stdout, err := cmd.StdoutPipe(); if err != nil { return fmt.Errorf("couldn't start plugin: %w", err) }
	if err := cmd.Start(); err != nil {
		return fmt.Errorf("couldn't start plugin: %w", err)
	}
	c.cmd = cmd; c.stdin = stdin; c.stdout = bufio.NewReader(stdout); c.started = true
	if c.ui == nil { c.ui = &pluginUI{pluginName: c.name} }
	return nil
}
func (c *pluginClient) close() {
	if c.stdin != nil { c.stdin.Close() }
	// Age seems to terminate plugins by closing stdin / process may be left; we kill if still running after done where appropriate.
	// For client flows, after successful completion, terminate process to avoid blocking.
	if c.cmd != nil && c.cmd.Process != nil {
		// Don't wait indefinitely; kill.
		c.cmd.Process.Kill()
		c.cmd.Wait()
	}
}

// stanza writing (for plugin messages), body encoded over possibly multiple lines exactly as format
func writeStanzaTo(w io.Writer, s *stanza) error {
	var sb strings.Builder
	sb.WriteString("-> "+s.Type)
	for _, a := range s.Args { sb.WriteString(" "+a) }
	sb.WriteString("\n")
	// body
	enc := b64Encode(s.Body)
	for len(enc) > 64 {
		sb.WriteString(enc[:64]+"\n"); enc = enc[64:]
	}
	sb.WriteString(enc+"\n")
	_, err := io.WriteString(w, sb.String())
	return err
}

// read one stanza from plugin/host stream using format stanza parser (for a single stanza, not header)
func readPluginStanza(br *bufio.Reader) (*stanza, error) {
	// This reads a single stanza (opening + body lines until short line)
	// Errors similar to header parsing
	line, err := br.ReadString('\n')
	if err != nil {
		if err == io.EOF { return nil, fmt.Errorf("failed to read line: EOF") }
		return nil, fmt.Errorf("failed to read line: %w", err)
	}
	if !strings.HasPrefix(line, "-> ") {
		return nil, fmt.Errorf("malformed stanza opening line: %q", line)
	}
	content := strings.TrimSuffix(line, "\n")
	// validate
	malformed := false
	for i:=0;i<len(content);i++ { if content[i] < 32 || content[i] > 126 { if content[i]!=' ' { malformed=true } } }
	fields := strings.Split(content[3:], " ")
	for _, f := range fields { if f=="" { malformed=true } }
	if malformed { return nil, fmt.Errorf("malformed stanza: %q", line) }
	st := &stanza{Type: fields[0], Args: append([]string{}, fields[1:]...)}
	for {
		bline, err := br.ReadString('\n')
		if err != nil {
			if err == io.EOF { return nil, fmt.Errorf("failed to read line: EOF") }
			return nil, fmt.Errorf("failed to read line: %w", err)
		}
		if strings.HasPrefix(bline, "-> ") || strings.HasPrefix(bline, "---") {
			return nil, fmt.Errorf("parsing age header: malformed body line %q: stanza ended without a short line\nnote: this might be a file encrypted with an old beta version of age or rage; use age v1.0.0-beta6 or rage to decrypt it", bline)
		}
		bcontent := strings.TrimSuffix(bline, "\n")
		decoded, derr := b64Decode(bcontent)
		if derr != nil { return nil, fmt.Errorf("parsing age header: malformed body line %q: %v", bline, derr) }
		if len(bcontent) > 64 { return nil, fmt.Errorf("parsing age header: malformed body line %q: too long", bline) }
		st.Body = append(st.Body, decoded...)
		if len(bcontent) < 64 { break }
	}
	return st, nil
}

// Plugin protocol handling: after initial send, loop reading plugin stanzas until done or satisfied.
// Handler callbacks process each plugin stanza and return response to send (or nil) and done flag.

type pluginSession struct {
	client *pluginClient
	labels []string
	recipientStanza *stanza
	fileKey []byte
	// For recipient: expected stanza index (0)
	expectedIndex int
}

func (s *pluginSession) handleStanza(st *stanza) (bool, error) {
	// returns true if this stanza satisfies the session (recipient-stanza with correct index or file-key)
	c := s.client
	switch st.Type {
	case "recipient-stanza":
		if len(st.Args) < 1 { // will be validated by caller? Plugin client expects at least index+type
			// Let caller check
		}
		// Validate format like original: need at least 2 args (index and stanza type)
		if len(st.Args) < 2 {
			// Original seems to reply unsupported? Actually for recipient-stanza without type, likely error malformed
			// Send unsupported and continue
			writeStanzaTo(c.stdin, &stanza{Type: "unsupported"})
			return false, nil
		}
		idx, err := strconv.Atoi(st.Args[0])
		if err != nil {
			writeStanzaTo(c.stdin, &stanza{Type: "unsupported"})
			return false, nil
		}
		if idx != s.expectedIndex {
			return false, fmt.Errorf("malformed recipient-stanza stanza: unexpected index")
		}
		// Response ok
		if err := writeStanzaTo(c.stdin, &stanza{Type: "ok"}); err != nil { return false, err }
		s.recipientStanza = &stanza{Type: st.Args[1], Args: append([]string{}, st.Args[2:]...), Body: st.Body}
		return true, nil
	case "file-key":
		if len(st.Args) != 1 {
			writeStanzaTo(c.stdin, &stanza{Type: "unsupported"})
			return false, nil
		}
		idx, err := strconv.Atoi(st.Args[0])
		if err != nil {
			writeStanzaTo(c.stdin, &stanza{Type: "unsupported"})
			return false, nil
		}
		// Index validation done by caller context: plugin may return for any stanza it was given; if out of range error
		// Caller sets expectedIndex as range max? Here we store and validate in caller after.
		if idx < 0 || idx > 1000000 {
			return false, fmt.Errorf("malformed file-key stanza: unexpected index")
		}
		// We need to know number of stanzas sent; stored in session field stanzaCount
		if idx >= s.stanzaCount {
			return false, fmt.Errorf("malformed file-key stanza: unexpected index")
		}
		if err := writeStanzaTo(c.stdin, &stanza{Type: "ok"}); err != nil { return false, err }
		s.fileKey = append([]byte{}, st.Body...)
		s.fileKeyIndex = idx
		return true, nil
	case "msg":
		// body is text (already base64 decoded)
		// Display to stderr: age: <name> plugin: <msg>
		// If msg does not end with newline, Go plugin UI adds? Original printed msg with newline: message body "Hello!" gave one line. If plugin msg already contains newline, it prints as is?
		text := string(st.Body)
		fmt.Fprintf(os.Stderr, "age: %s plugin: %s", c.name, text)
		if !strings.HasSuffix(text, "\n") { fmt.Fprintf(os.Stderr, "\n") }
		writeStanzaTo(c.stdin, &stanza{Type: "ok"})
		return false, nil
	case "request-secret":
		// prompt is body text
		promptText := string(st.Body)
		val, err := c.ui.requestSecret(promptText)
		if err != nil {
			// warning already printed by UI? UI returns error; we log warning
			logWarning("could not read value for age-plugin-%s: %v", c.name, err)
			writeStanzaTo(c.stdin, &stanza{Type: "fail"})
			return false, nil
		}
		// reply ok with body = secret (stanza Body will be base64 encoded on wire)
		writeStanzaTo(c.stdin, &stanza{Type: "ok", Body: []byte(val)})
		return false, nil
	case "confirm":
		if len(st.Args) < 1 || len(st.Args) > 2 {
			return false, fmt.Errorf("malformed confirm stanza: unexpected number of arguments")
		}
		yesBytes, err := decodePluginOption(st.Args[0]); if err != nil { return false, fmt.Errorf("malformed confirm stanza: invalid YES option encoding") }
		var noBytes []byte
		if len(st.Args) == 2 {
			noBytes, err = decodePluginOption(st.Args[1]); if err != nil { return false, fmt.Errorf("malformed confirm stanza: invalid NO option encoding") }
		}
		selected, err := c.ui.confirm(string(st.Body), string(yesBytes), string(noBytes), len(st.Args)==2)
		if err != nil {
			logWarning("could not read value for age-plugin-%s: %v", c.name, err)
			writeStanzaTo(c.stdin, &stanza{Type: "fail"})
			return false, nil
		}
		// response: ok with arg = selected option string
		writeStanzaTo(c.stdin, &stanza{Type: "ok", Args: []string{selected}})
		return false, nil
	case "labels":
		if len(st.Args) < 1 {
			// stanza without args is malformed stanza? That is parsed earlier as malformed due trailing? labels with no args but line "-> labels" has one field type only, our parser allows fields[0]=labels and empty args. Original error was malformed stanza: "-> labels \n" when line had trailing space. When line is "-> labels" without args, need check original. Approx: respond ok and set empty?
		}
		s.labels = sortLabels(st.Args)
		writeStanzaTo(c.stdin, &stanza{Type: "ok"})
		return false, nil
	case "error":
		// original: replies ok then (?) returns error whose text is body
		// It printed error as 'foo plugin: <msg>' at top level. Response ok may be sent but process exit may close.
		// We can send ok before returning
		writeStanzaTo(c.stdin, &stanza{Type: "ok"})
		return false, fmt.Errorf("%s", string(st.Body))
	case "unsupported", "ok", "fail", "done":
		// For other plugin-sent stanzas that are responses, host replies unsupported unless it's done
		if st.Type == "done" {
			// plugin indicates end without satisfying; caller will handle unsatisfied
			return false, &pluginDoneError{}
		}
		writeStanzaTo(c.stdin, &stanza{Type: "unsupported"})
		return false, nil
	default:
		writeStanzaTo(c.stdin, &stanza{Type: "unsupported"})
		return false, nil
	}
}

type pluginDoneError struct{}
func (e *pluginDoneError) Error() string { return "done" }

func decodePluginOption(s string) ([]byte, error) {
	// strict raw base64 decoding
	b, err := b64DecodeStrict(s)
	return b, err
}
func b64DecodeStrict(s string) ([]byte, error) {
	// Go's RawStdEncoding.Strict() ?
	return b64StrictDecode(s)
}

// Plugin recipients
type pluginRecipient struct {
	name string
	recipientString string // full age1... string for add-recipient
	identityString string // for add-identity case (when constructed via -j or -i identity)
	isIdentity bool
	client *pluginClient
}
func newPluginRecipient(s string) (recipient, error) {
	// decode bech32 any
	hrp, _, err := bech32DecodeAny(s)
	if err != nil { return nil, fmt.Errorf("invalid recipient encoding: %w", err) }
	if !strings.HasPrefix(hrp, "age1") || len(hrp) <= 4 { return nil, fmt.Errorf("invalid recipient encoding: invalid plugin recipient") }
	name := hrp[4:]
	if name == "" { return nil, fmt.Errorf("invalid recipient encoding: invalid plugin recipient") }
	return &pluginRecipient{name: name, recipientString: s, client: &pluginClient{name: name}}, nil
}
func newPluginRecipientFromIdentity(name, identityString string) recipient {
	return &pluginRecipient{name: name, identityString: identityString, isIdentity: true, client: &pluginClient{name: name}}
}
func (r *pluginRecipient) wrap(fileKey []byte) (*stanza, []string, error) {
	c := r.client
	if c == nil { c = &pluginClient{name: r.name}; r.client = c }
	if err := c.start("recipient-v1"); err != nil {
		return nil, nil, fmt.Errorf("%s plugin: %w", r.name, err)
	}
	defer c.close()
	// send initial stanzas
	if r.isIdentity {
		if err := writeStanzaTo(c.stdin, &stanza{Type: "add-identity", Args: []string{r.identityString}}); err != nil { return nil, nil, fmt.Errorf("%s plugin: %w", r.name, err) }
	} else {
		if err := writeStanzaTo(c.stdin, &stanza{Type: "add-recipient", Args: []string{r.recipientString}}); err != nil { return nil, nil, fmt.Errorf("%s plugin: %w", r.name, err) }
	}
	maybeWriteGrease(c.stdin)
	if err := writeStanzaTo(c.stdin, &stanza{Type: "wrap-file-key", Body: fileKey}); err != nil { return nil, nil, fmt.Errorf("%s plugin: %w", r.name, err) }
	if err := writeStanzaTo(c.stdin, &stanza{Type: "extension-labels"}); err != nil { return nil, nil, fmt.Errorf("%s plugin: %w", r.name, err) }
	if err := writeStanzaTo(c.stdin, &stanza{Type: "done"}); err != nil { return nil, nil, fmt.Errorf("%s plugin: %w", r.name, err) }
	// Read plugin stanzas until recipient stanza satisfied and then done or recipient stanza received
	// Original seems to read until file... It reads continuously until done; if recipient-stanza is received, it continues reading until done to process requests like labels after?
	session := &pluginSession{client: c, expectedIndex: 0, stanzaCount: 1}
	for {
		st, err := readPluginStanza(c.stdout)
		if err != nil {
			return nil, nil, fmt.Errorf("%s plugin: %w", r.name, err)
		}
		if st.Type == "done" {
			if session.recipientStanza != nil {
				return session.recipientStanza, session.labels, nil
			}
			// done without recipient stanza: original likely expects... treat as error? Real plugins always return stanza.
			return nil, nil, fmt.Errorf("%s plugin: no recipient stanza", r.name)
		}
		satisfied, herr := session.handleStanza(st)
		if herr != nil {
			if _, ok := herr.(*pluginDoneError); ok {
				if session.recipientStanza != nil { return session.recipientStanza, session.labels, nil }
				return nil, nil, fmt.Errorf("%s plugin: no recipient stanza", r.name)
			}
			// error stanza produces error with plugin name prefix
			if st.Type == "error" {
				return nil, nil, fmt.Errorf("%s plugin: %w", r.name, herr)
			}
			return nil, nil, fmt.Errorf("%s plugin: %w", r.name, herr)
		}
		_ = satisfied
	}
}

// Plugin identities
type pluginIdentity struct {
	name string
	identityString string
	client *pluginClient
}
func newPluginIdentityFromString(name, identityString string) identity {
	return &pluginIdentity{name: name, identityString: identityString, client: &pluginClient{name: name}}
}
func newPluginIdentity(name string) *pluginIdentity {
	// identity string for -j: AGE-PLUGIN-<UPPER NAME>-1<checksum of empty>
	hrp := "AGE-PLUGIN-" + strings.ToUpper(name) + "-"
	s := bech32EncodeUpper(hrp, nil)
	return &pluginIdentity{name: name, identityString: s, client: &pluginClient{name: name}}
}
func bech32EncodeUpper(hrp string, data []byte) string {
	// hrp is already uppercase; bech32Encode detects uppercase
	return bech32Encode(hrp, data)
}
func (i *pluginIdentity) unwrap(stanzas []*stanza) ([]byte, error) {
	c := i.client
	if c == nil { c = &pluginClient{name: i.name}; i.client = c }
	if err := c.start("identity-v1"); err != nil {
		return nil, fmt.Errorf("%s plugin: %w", i.name, err)
	}
	defer c.close()
	if err := writeStanzaTo(c.stdin, &stanza{Type: "add-identity", Args: []string{i.identityString}}); err != nil { return nil, fmt.Errorf("%s plugin: %w", i.name, err) }
	maybeWriteGrease(c.stdin)
	for idx, s := range stanzas {
		args := append([]string{fmt.Sprint(idx), s.Type}, s.Args...)
		if err := writeStanzaTo(c.stdin, &stanza{Type: "recipient-stanza", Args: args, Body: s.Body}); err != nil { return nil, fmt.Errorf("%s plugin: %w", i.name, err) }
	}
	if err := writeStanzaTo(c.stdin, &stanza{Type: "done"}); err != nil { return nil, fmt.Errorf("%s plugin: %w", i.name, err) }
	session := &pluginSession{client: c, expectedIndex: 0, stanzaCount: len(stanzas)}
	for {
		st, err := readPluginStanza(c.stdout)
		if err != nil {
			return nil, fmt.Errorf("%s plugin: %w", i.name, err)
		}
		if st.Type == "done" {
			if session.fileKey != nil { return session.fileKey, nil }
			return nil, errNoMatch
		}
		satisfied, herr := session.handleStanza(st)
		if herr != nil {
			if _, ok := herr.(*pluginDoneError); ok {
				if session.fileKey != nil { return session.fileKey, nil }
				return nil, errNoMatch
			}
			if st.Type == "error" {
				return nil, fmt.Errorf("%s plugin: %w", i.name, herr)
			}
			return nil, fmt.Errorf("%s plugin: %w", i.name, herr)
		}
		_ = satisfied
	}
}

