		if len(st.Args) < 1 || len(st.Args) > 2 {
			return false, fmt.Errorf("malformed confirm stanza: unexpected number of arguments")
		}
		yesBytes, err := decodePluginOption(st.Args[0]); if err != nil { return false, fmt.Errorf("malformed confirm stanza: invalid YES option encoding") }
