func pluginNotFoundError(name string) error {
	// Exec lookpath error mimics Go: exec: "age-plugin-foo": executable file not found in $PATH
	return fmt.Errorf("couldn't start plugin: %q plugin not found: exec: %q: executable file not found in $PATH", name, "age-plugin-"+name)
}

func (c *pluginClient) start(phase string) error {
	if c.started { return nil }
	path, err := exec.LookPath("age-plugin-" + c.name)
	if err != nil {
		return pluginNotFoundError(c.name)
	}
	_ = path
