	// Original seems to read until file... It reads continuously until done; if recipient-stanza is received, it continues reading until done to process requests like labels after?
	session := &pluginSession{client: c, expectedIndex: 0, stanzaCount: 1}
	for {
		st, err := readPluginStanza(c.stdout)
		if err != nil {
			return nil, nil, fmt.Errorf("%s plugin: %w", r.name, err)
		}
		if st.Type == "done" {
			if session.recipientStanza != nil {
				return session.recipientStanza, session.labels, nil
			}
			// done without recipient stanza: original likely expects... treat as error? Real plugins always return stanza.
			return nil, nil, fmt.Errorf("%s plugin: no recipient stanza", r.name)
		}
		satisfied, herr := session.handleStanza(st)
		if herr != nil {
			if _, ok := herr.(*pluginDoneError); ok {
				if session.recipientStanza != nil { return session.recipientStanza, session.labels, nil }
				return nil, nil, fmt.Errorf("%s plugin: no recipient stanza", r.name)
			}
			// error stanza produces error with plugin name prefix
			if st.Type == "error" {
				return nil, nil, fmt.Errorf("%s plugin: %w", r.name, herr)
			}
			return nil, nil, fmt.Errorf("%s plugin: %w", r.name, herr)
		}
		_ = satisfied
	}
}

// Plugin identities
type pluginIdentity struct {
	name string
	identityString string
	client *pluginClient
}
func newPluginIdentityFromString(name, identityString string) identity {
	return &pluginIdentity{name: name, identityString: identityString, client: &pluginClient{name: name}}
}
func newPluginIdentity(name string) *pluginIdentity {
	// identity string for -j: AGE-PLUGIN-<UPPER NAME>-1<checksum of empty>
	hrp := "AGE-PLUGIN-" + strings.ToUpper(name) + "-"
	s := bech32EncodeUpper(hrp, nil)
	return &pluginIdentity{name: name, identityString: s, client: &pluginClient{name: name}}
}
func bech32EncodeUpper(hrp string, data []byte) string {
	// hrp is already uppercase; bech32Encode detects uppercase
	return bech32Encode(hrp, data)
}
func (i *pluginIdentity) unwrap(stanzas []*stanza) ([]byte, error) {
	c := i.client
	if c == nil { c = &pluginClient{name: i.name}; i.client = c }
	if err := c.start("identity-v1"); err != nil {
		return nil, fmt.Errorf("%s plugin: %w", i.name, err)
	}
	defer c.close()
	if err := writeStanzaTo(c.stdin, &stanza{Type: "add-identity", Args: []string{i.identityString}}); err != nil { return nil, fmt.Errorf("%s plugin: %w", i.name, err) }
	maybeWriteGrease(c.stdin)
	for idx, s := range stanzas {
		args := append([]string{fmt.Sprint(idx), s.Type}, s.Args...)
		if err := writeStanzaTo(c.stdin, &stanza{Type: "recipient-stanza", Args: args, Body: s.Body}); err != nil { return nil, fmt.Errorf("%s plugin: %w", i.name, err) }
	}
	if err := writeStanzaTo(c.stdin, &stanza{Type: "done"}); err != nil { return nil, fmt.Errorf("%s plugin: %w", i.name, err) }
	session := &pluginSession{client: c, expectedIndex: 0, stanzaCount: len(stanzas)}
	for {
		st, err := readPluginStanza(c.stdout)
		if err != nil {
			return nil, fmt.Errorf("%s plugin: %w", i.name, err)
		}
		if st.Type == "done" {
			if session.fileKey != nil { return session.fileKey, nil }
			return nil, errNoMatch
		}
		satisfied, herr := session.handleStanza(st)
		if herr != nil {
			if _, ok := herr.(*pluginDoneError); ok {
				if session.fileKey != nil { return session.fileKey, nil }
				return nil, errNoMatch
			}
			if st.Type == "error" {
				return nil, fmt.Errorf("%s plugin: %w", i.name, herr)
			}
			return nil, fmt.Errorf("%s plugin: %w", i.name, herr)
		}
		_ = satisfied
	}
}

