func uncompressP256(c []byte) ([]byte, error) {
	if len(c)!=33 || (c[0]!=2 && c[0]!=3) { return nil, fmt.Errorf("invalid P256 point encoding") }
	xx, yy := elliptic.UnmarshalCompressed(elliptic.P256(), c)
