{"command":"cat > /workspace/identity.go <<'EOF'
package main

import (
	"fmt"
	"os"
	"strings"
)

// Parse SSH identity file (contents start with -----BEGIN)
func parseSSHIdentityFile(contents []byte, name string, passphrase []byte, hasPass bool) ([]identity, error) {
	parsedRaw, err := parseSSHPrivateKey(contents, passphrase, hasPass)
	if err != nil {
		return nil, fmt.Errorf("malformed SSH identity in %q: %w", name, err)
	}
	switch v := parsedRaw.(type) {
	case *sshRSAIdentity:
		return []identity{v}, nil
	case *sshEdIdentity:
		return []identity{v}, nil
	case *opensshKeyParsed:
		if v.encrypted != nil {
			lz := &lazySSHIdentity{filename: name, contents: append([]byte{}, contents...), parsed: v}
			return []identity{lz}, nil
		}
		if v.identity != nil {
			switch id := v.identity.(type) {
			case *sshRSAIdentity: return []identity{id}, nil
			case *sshEdIdentity: return []identity{id}, nil
			default: return nil, fmt.Errorf("malformed SSH identity in %q: unsupported SSH identity type: %T", name, v.identity)
			}
		}
		return nil, fmt.Errorf("malformed SSH identity in %q: ssh: no key found", name)
	case *encryptedPEMBlock:
		lz := &lazySSHIdentity{filename: name, contents: append([]byte{}, contents...), pemEncrypted: v}
		return []identity{lz}, nil
	default:
		return nil, fmt.Errorf("malformed SSH identity in %q: ssh: no key found", name)
	}
}

type lazySSHIdentity struct {
	filename string
	contents []byte
	parsed *opensshKeyParsed
	pemEncrypted *encryptedPEMBlock
	decrypted identity // after prompt
}
func (l *lazySSHIdentity) publicParts() (string, string, bool) {
	// returns stanza type and tag string if determinable
	if l.parsed != nil && l.parsed.pubKey != nil {
		sp := l.parsed.pubKey
		tag := b64Encode(sshTag(sp.Blob))
		if sp.Kind == "ssh-rsa" { return "ssh-rsa", tag, true }
		if sp.Kind == "ssh-ed25519" { return "ssh-ed25519", tag, true }
	}
	if l.parsed != nil && l.parsed.encrypted != nil && l.parsed.encrypted.pubBlob != nil {
		if sp, err := parseSSHPublicBlob(l.parsed.encrypted.pubBlob); err == nil {
			tag := b64Encode(sshTag(sp.Blob))
			return sp.Kind, tag, true
		}
	}
	return "", "", false
}
func (l *lazySSHIdentity) unwrap(stanzas []*stanza) ([]byte, error) {
	if l.decrypted != nil { return l.decrypted.unwrap(stanzas) }
	typ, tag, ok := l.publicParts()
	if ok {
		matched := false
		for _, s := range stanzas {
			if s.Type == typ && len(s.Args)>=1 && s.Args[0]==tag { matched = true }
		}
		if !matched { return nil, errNoMatch }
	}
	// prompt passphrase
	prompt := fmt.Sprintf("Enter passphrase for %q: ", l.filename)
	pass, err := readSecretValue(prompt)
	if err != nil {
		return nil, fmt.Errorf("could not read passphrase: %w", err) // wrapping checked later; original SSH passphrase prompt errors unknown exact for no tty
	}
	// decrypt
	var id interface{}
	var derr error
	if l.pemEncrypted != nil {
		// traditional PEM
		id, derr = parseSSHPrivateKey(l.contents, []byte(pass), true)
	} else {
		// parseOpenSSH with passphrase
		parsed, err := parseOpenSSH(l.contents, []byte(pass), true)
		// parseOpenSSH expects DER bytes, not PEM. Need decode PEM block.
		_ = parsed; _ = err
		// Use parseSSHPrivateKey which handles PEM
		id, derr = parseSSHPrivateKey(l.contents, []byte(pass), true)
	}
	if derr != nil {
		return nil, fmt.Errorf("failed to decrypt SSH key file: %w", derr)
	}
	switch v := id.(type) {
	case *sshRSAIdentity: l.decrypted = v
	case *sshEdIdentity: l.decrypted = v
