		return nil, fmt.Errorf("failed to decrypt identity file: %w", err)
	}
	// parse plaintext identities
	if bytes.HasPrefix(plaintext, []byte("-----BEGIN")) {
		ids, err := parseSSHIdentityFile(plaintext, name, nil, false)
		if err != nil {
			// For decrypted SSH, original likely returns this err directly? It would include malformed SSH identity in "name"
			return nil, err
		}
		return ids, nil
	}
	ids, err := parseIdentityLines(plaintext)
	if err != nil {
		return nil, err
	}
	return ids, nil
}

func decryptWithHeaderNoArmor(h *header, br *bufio.Reader, identities []identity) (*streamReader, error) {
	return decryptWithHeader(h, br, identities, nil)
}

// classifyIdentityFileContents returns:
// - lazy encrypted identity if contents is age file (armored decoded or binary)
// - decoded contents to use for normal parsing if armored but not age
// - original contents otherwise
// - special error if armor decoding fails (err is full error after "reading %q: " wrapper handling at caller)
func classifyIdentityContents(name string, contents []byte) (lazy *encryptedIdentityFile, usable []byte, armorErr error) {
	// Check armor detection similar to general input: first non-blank line trimmed starts with BEGIN AGE ?
	lines := bytes.SplitAfterN(contents, []byte("\n"), 10)
	isArmorCandidate := false
	for _, ln := range lines {
		t := string(bytes.TrimSpace(ln))
		if t == "" { continue }
		if len(t) >= len("-----BEGIN AGE ENCRYPTED FILE-----") && t[:len("-----BEGIN AGE ENCRYPTED FILE-----")] == "-----BEGIN AGE ENCRYPTED FILE-----" {
			isArmorCandidate = true
		}
		break
	}
	if isArmorCandidate {
		ar := newArmorReader(bytes.NewReader(contents))
		decoded, err := io.ReadAll(ar)
		if err != nil {
			// return error mirroring "failed to read %q: %w" - caller wraps with reading %q:
			return nil, nil, fmt.Errorf("failed to read %q: %w", name, err)
		}
		if err := ar.checkTrailing(); err != nil {
			return nil, nil, fmt.Errorf("failed to read %q: %w", name, err)
		}
		if bytes.HasPrefix(decoded, []byte("age-encryption.org/v1\n")) {
			return &encryptedIdentityFile{name: name, contents: decoded}, nil, nil
		}
		return nil, decoded, nil
	}
	if bytes.HasPrefix(contents, []byte("age-encryption.org/v1\n")) {
		return &encryptedIdentityFile{name: name, contents: contents}, nil, nil
	}
	return nil, contents, nil
}
