// hinted error
type hintedError struct {
	err error
	hints []string
}
func (e *hintedError) Error() string { return e.err.Error() }
func (e *hintedError) Unwrap() error { return e.err }
func withHints(err error, hints ...string) error { return &hintedError{err: err, hints: hints} }

type pluginNotFoundError struct {
	name string
	msg string
}
func (e *pluginNotFoundError) Error() string { return e.msg }

func printErrorAndExitCode(err error) int {
	// collect hints
	var hints []string
	var he *hintedError
	if errorAs(err, &he) { hints = append(hints, he.hints...) }
	// plugin not found hints
	var pnf *pluginNotFoundError
	if errorAs(err, &pnf) {
		hints = append(hints, fmt.Sprintf("you might want to install the %q plugin", pnf.name))
		hints = append(hints, "visit https://age-encryption.org/awesome#plugins for a list of available plugins")
	}
	fmt.Fprintf(os.Stderr, "age: error: %v\n", err)
	for _, h := range hints {
		fmt.Fprintf(os.Stderr, "age: hint: %s\n", h)
	}
	fmt.Fprintf(os.Stderr, "age: report unexpected or unhelpful errors at https://filippo.io/age/report\n")
	return 1
}
func errorAs(err error, target interface{}) bool {
	switch t := target.(type) {
	case **hintedError:
		for err != nil {
			if v, ok := err.(*hintedError); ok { *t = v; return true }
			u, ok := err.(interface{ Unwrap() error }); if !ok { return false }; err = u.Unwrap()
		}
		return false
	case **pluginNotFoundError:
		for err != nil {
			if v, ok := err.(*pluginNotFoundError); ok { *t = v; return true }
			u, ok := err.(interface{ Unwrap() error }); if !ok { return false }; err = u.Unwrap()
		}
		return false
	default:
		return false
	}
}

