// hinted error
type hintedError struct {
	err error
	hints []string
}
func (e *hintedError) Error() string { return e.err.Error() }
func (e *hintedError) Unwrap() error { return e.err }
func withHints(err error, hints ...string) error { return &hintedError{err: err, hints: hints} }

type pluginNotFoundError struct {
	name string
	msg string
}
func (e *pluginNotFoundError) Error() string { return e.msg }

func printErrorAndExitCode(err error) int {
	// collect hints
	var hints []string
	var he *hintedError
	if errorAs(err, &he) { hints = append(hints, he.hints...) }
	// plugin not found hints
	var pnf *pluginNotFoundError
	if errorAs(err, &pnf) {
		hints = append(hints, fmt.Sprintf("you might want to install the %q plugin", pnf.name))
		hints = append(hints, "visit https://age-encryption.org/awesome#plugins for a list of available plugins")
	}
	fmt.Fprintf(os.Stderr, "age: error: %v\n", err)
	for _, h := range hints {
		fmt.Fprintf(os.Stderr, "age: hint: %s\n", h)
	}
	fmt.Fprintf(os.Stderr, "age: report unexpected or unhelpful errors at https://filippo.io/age/report\n")
	return 1
}
func errorAs(err error, target interface{}) bool {
	switch t := target.(type) {
	case **hintedError:
		for err != nil {
			if v, ok := err.(*hintedError); ok { *t = v; return true }
			u, ok := err.(interface{ Unwrap() error }); if !ok { return false }; err = u.Unwrap()
		}
		return false
	case **pluginNotFoundError:
		for err != nil {
			if v, ok := err.(*pluginNotFoundError); ok { *t = v; return true }
			u, ok := err.(interface{ Unwrap() error }); if !ok { return false }; err = u.Unwrap()
		}
		return false
	default:
		return false
	}
}

// Flag value types
type stringListValue struct { list *[]string }
func (s stringListValue) String() string { if s.list==nil { return "" }; return strings.Join(*s.list, ",") }
func (s stringListValue) Set(v string) error { *s.list = append(*s.list, v); return nil }

type identityItem struct { kind string; value string } // kind file/plugin
type orderedIdentityFlags struct { items *[]identityItem; kind string }
func (o orderedIdentityFlags) String() string { return "" }
func (o orderedIdentityFlags) Set(v string) error { *o.items = append(*o.items, identityItem{kind: o.kind, value: v}); return nil }

func main() { os.Exit(run()) }

func run() int {
	// flags
	var encryptFlag, decryptFlag, armorFlag, passphraseFlag, versionFlag bool
	var outputName string
	var recipients []string
	var recipientsFiles []string
	var identityItems []identityItem

	flag.Usage = func() { fmt.Fprint(flag.CommandLine.Output(), usageText) }
	// bool flags with both names
	flag.BoolVar(&encryptFlag, "e", false, "")
	flag.BoolVar(&encryptFlag, "encrypt", false, "")
	flag.BoolVar(&decryptFlag, "d", false, "")
	flag.BoolVar(&decryptFlag, "decrypt", false, "")
	flag.BoolVar(&armorFlag, "a", false, "")
	flag.BoolVar(&armorFlag, "armor", false, "")
	flag.BoolVar(&passphraseFlag, "p", false, "")
	flag.BoolVar(&passphraseFlag, "passphrase", false, "")
	flag.BoolVar(&versionFlag, "version", false, "")
	flag.StringVar(&outputName, "o", "", "")
	flag.StringVar(&outputName, "output", "", "")
	rv := stringListValue{list: &recipients}
	flag.Var(rv, "r", "")
	flag.Var(rv, "recipient", "")
	rfv := stringListValue{list: &recipientsFiles}
	flag.Var(rfv, "R", "")
	flag.Var(rfv, "recipients-file", "")
	identItems := []identityItem{}
	identityItems = identItems // placeholder replaced: need use shared variable defined above, assign empty
	identityItems = []identityItem{}
	iv := orderedIdentityFlags{items: &identityItems, kind: "file"}
	flag.Var(iv, "i", "")
	flag.Var(iv, "identity", "")
	jv := orderedIdentityFlags{items: &identityItems, kind: "plugin"}
	flag.Var(jv, "j", "")

	flag.Parse()
