	if len(identityItems) > 0 && !encryptFlag {
		return printErrorAndExitCode(withHints(fmt.Errorf("-i/--identity and -j can't be used in encryption mode unless symmetric encryption is explicitly selected with -e/--encrypt"), "did you forget to specify -d/--decrypt?"))
