func tooManyInputError(args []string) error {
	quoted := make([]string, len(args))
	for i,a := range args { quoted[i] = fmt.Sprintf("%q", a) }
	base := fmt.Errorf("too many INPUT arguments: %s", strings.Join(quoted, " "))
	if len(args) >= 2 && strings.HasPrefix(args[1], "-") {
		// build suggestion
		prefixTokens := []string{}
		boundary := len(os.Args) - len(args)
		if boundary > 1 {
			prefixTokens = append(prefixTokens, os.Args[1:boundary]...)
		}
		suggestTokens := append(append(append([]string{}, prefixTokens...), args[1:]...), args[0])
		allTokens := append([]string{os.Args[0]}, suggestTokens...)
		if allSafeTokens(allTokens) {
			suggested := strings.Join(allTokens, " ")
			return withHints(base, "the input file must be specified after all flags", "did you mean:", "    "+suggested)
		}
		return withHints(base, "the input file must be specified after all flags")
	}
	return withHints(base, "only a single input file may be specified at a time")
}
func allSafeTokens(tokens []string) bool {
	for _, t := range tokens {
		if t == "" { return false }
		for i:=0;i<len(t);i++ {
			c := t[i]
			ok := (c>='a'&&c<='z')||(c>='A'&&c<='Z')||(c>='0'&&c<='9')|| strings.ContainsRune("._%+-/=:,@-", rune(c))
			if !ok { return false }
		}
	}
	return true
}

// duplicate warnings
func warnDuplicates(recipients, recipientsFiles []string, identityItems []identityItem) {
	seen := map[string]bool{}; warned := map[string]bool{}
	_ = seen; _ = warned
	// recipients
	seenMap := map[string]bool{}; warnMap := map[string]bool{}
	for _, v := range recipients {
		if seenMap[v] && !warnMap[v] { logWarning("duplicate recipient %q", v); warnMap[v]=true }
		seenMap[v]=true
	}
	seenMap = map[string]bool{}; warnMap = map[string]bool{}
	for _, v := range recipientsFiles {
		if seenMap[v] && !warnMap[v] { logWarning("duplicate recipients file %q", v); warnMap[v]=true }
		seenMap[v]=true
	}
	seenMap = map[string]bool{}; warnMap = map[string]bool{}
	for _, it := range identityItems {
		if it.kind != "file" { continue }
		v := it.value
		if seenMap[v] && !warnMap[v] { logWarning("duplicate identity file %q", v); warnMap[v]=true }
		seenMap[v]=true
	}
}

// open input helpers
func openInputFile(inputName string) (io.ReadCloser, bool, error) {
	// bool indicates stdin
	if inputName == "" || inputName == "-" {
		return io.NopCloser(os.Stdin), true, nil
	}
	f, err := os.Open(inputName)
	if err != nil {
		return nil, false, fmt.Errorf("failed to open input file %q: %w", inputName, err)
	}
	return f, false, nil
}
func checkSameFile(inputName, outputName string) error {
	if inputName == "" || inputName == "-" || outputName == "" || outputName == "-" { return nil }
	ai, err1 := filepath.Abs(inputName)
	ao, err2 := filepath.Abs(outputName)
	if err1 == nil && err2 == nil && ai == ao {
		return fmt.Errorf("input and output files are the same: %q", outputName)
	}
	return nil
}

// encrypt main
func encryptMain(inputName, outputName string, recipientStrings, recipientsFiles []string, identityItems []identityItem, passphrase bool, armor bool) error {
	// duplicate warnings
	// identity duplicates already will be included
	warnDuplicates(recipientStrings, recipientsFiles, identityItems)
	in, isStdin, err := openInputFile(inputName)
	if err != nil { return err }
	if !isStdin { defer in.Close() }
	_ = isStdin
	if err := checkSameFile(inputName, outputName); err != nil { return err }
	// TTY output check
	if outputName == "" && !armor && isTerminalFd(os.Stdout.Fd()) {
		return withHints(fmt.Errorf("refusing to output binary to the terminal"), "did you mean to use -a/--armor?", "force anyway with \"-o -\"")
	}
	inputIsStdin := (inputName == "" || inputName == "-")
	tracker := &stdinTracker{}
	if inputIsStdin { tracker.used = true; tracker.usedFor = "input" }
	var recips []recipient
	if passphrase {
		pass, err := getEncryptPassphrase()
		if err != nil { return err }
		recips = append(recips, &scryptRecipient{passphrase: pass})
	} else {
		// parse -r
		for _, rs := range recipientStrings {
			r, err := parseRecipient(rs); if err != nil { return err }; recips = append(recips, r)
		}
		// parse -R
		for _, rf := range recipientsFiles {
			rs, err := parseRecipientsFile(rf, inputIsStdin, tracker, logWarning)
			if err != nil { return err }
			recips = append(recips, rs...)
		}
		// parse ordered identities/plugins
		for _, item := range identityItems {
			if item.kind == "file" {
				ids, err := readIdentityFileCLI(item.value, tracker, inputIsStdin)
				if err != nil { return err }
				for _, id := range ids {
					rs, err := identityToRecipients(id)
					if err != nil { return err }
					recips = append(recips, rs...)
				}
			} else { // plugin
				if !isValidPluginName(item.value) {
					return fmt.Errorf("initializing %q: invalid plugin name: %q", item.value, item.value)
				}
				pi := newPluginIdentity(item.value)
				recips = append(recips, &pluginRecipient{name: item.value, identityString: pi.identityString, isIdentity: true, client: &pluginClient{name: item.value}})
			}
		}
	}
	// output writer
	var outWriter io.Writer
	var lazy *lazyFileWriter
	if outputName == "" || outputName == "-" {
		outWriter = os.Stdout
	} else {
		lazy = &lazyFileWriter{name: outputName}
		outWriter = lazy
	}
	stream, err := encryptStream(outWriter, recips, armor)
	if err != nil { return err }
	_, copyErr := io.Copy(stream, in)
	if copyErr != nil { return copyErr }
	if err := stream.Close(); err != nil { return err }
	if lazy != nil {
		if err := lazy.Close(); err != nil { return err }
	}
	return nil
}

// decrypt main
func decryptMain(inputName, outputName string, identityItems []identityItem) error {
	// duplicate warnings only for identity files
	warnDuplicates(nil, nil, identityItems)
	in, isStdin, err := openInputFile(inputName)
	if err != nil { return err }
	if !isStdin { defer in.Close() }
	if err := checkSameFile(inputName, outputName); err != nil { return err }
	inputIsStdin := (inputName == "" || inputName == "-")
	tracker := &stdinTracker{}
	if inputIsStdin { tracker.used = true; tracker.usedFor = "input" }
	// build identities in ordered items
	var identities []identity
	userSpecified := len(identityItems) > 0
	for _, item := range identityItems {
		if item.kind == "file" {
			ids, err := readIdentityFileCLI(item.value, tracker, inputIsStdin)
			if err != nil { return err }
			identities = append(identities, ids...)
		} else {
			if !isValidPluginName(item.value) {
				return fmt.Errorf("initializing %q: invalid plugin name: %q", item.value, item.value)
			}
			identities = append(identities, newPluginIdentity(item.value))
		}
	}
	// read header / decrypt
	// wrap input in bufio
	brRaw := bufio.NewReader(in)
	reader, armorReaderObj, h, err := decryptSetup(brRaw, identities, userSpecified)
	if err != nil { return err }
	_ = h
	// open output after successful header
	var outWriter io.Writer
	var outFile *os.File
	if outputName == "" || outputName == "-" {
		outWriter = os.Stdout
	} else {
		f, err := os.Create(outputName)
		if err != nil { return err }
		outFile = f; outWriter = f
	}
	_, copyErr := io.Copy(outWriter, reader)
	if copyErr != nil {
		if outFile != nil { outFile.Close() }
		return copyErr
	}
	if armorReaderObj != nil {
		if err := armorReaderObj.checkTrailing(); err != nil {
			if outFile != nil { outFile.Close() }
			return err
		}
	}
	if outFile != nil {
		if err := outFile.Close(); err != nil { return err }
	}
	return nil
}

// decryptSetup parses header (handling armor), attempts identities, returns stream reader.
func decryptSetup(brRaw *bufio.Reader, identities []identity, userSpecified bool) (*streamReader, *armorReader, *header, error) {
	// armor detection: read first nonblank lines, store them
	var stored bytes.Buffer
	var candidate bool
	var sawLine bool
	// We need to peek line by line: use ReadString on brRaw and store into buffer feeding a multi reader
	for {
		line, err := brRaw.ReadString('\n')
		if len(line) > 0 {
			stored.WriteString(line)
			if strings.TrimSpace(line) != "" {
				sawLine = true
				t := strings.TrimSpace(line)
				if strings.HasPrefix(t, armorBegin) { candidate = true }
				break
			}
			// blank line: continue to next line unless EOF
			if err != nil { break }
			continue
		}
		if err != nil { break }
	}
	_ = sawLine
	var baseReader io.Reader
	if stored.Len() > 0 {
		baseReader = io.MultiReader(bytes.NewReader(stored.Bytes()), brRaw)
	} else {
		baseReader = brRaw
	}
	var ar *armorReader
	var effective io.Reader = baseReader
	if candidate {
		ar = newArmorReader(baseReader)
		effective = ar
	}
	br := bufio.NewReader(effective)
	h, err := parseHeaderFromReader(br)
	if err != nil {
		// err is *headerError with msg
		return nil, nil, nil, fmt.Errorf("failed to read header: %w", err)
	}
	// identities
	ids := identities
	specified := userSpecified
	if !specified {
		prompt := "Enter passphrase: "
		scryptId := &scryptIdentity{passphraseFunc: func() (string, error) {
			return readPassphraseForPrompt(prompt)
		}}
		ids = []identity{scryptId}
	}
	sr, err := decryptWithHeader(h, br, ids, ar)
	if err != nil {
		if err == errNoMatch {
			// diagnostics
			if len(h.Stanzas)==1 && h.Stanzas[0].Type=="scrypt" && specified {
				return nil, nil, nil, withHints(fmt.Errorf("file is passphrase-encrypted but identities were specified with -i/--identity or -j"), "remove all -i/--identity/-j flags to decrypt passphrase-encrypted files")
			}
			if !specified {
				return nil, nil, nil, withHints(fmt.Errorf("the file is not passphrase-encrypted, identities are required"), "specify identities with -i/--identity or -j to decrypt this file")
			}
			return nil, nil, nil, fmt.Errorf("no identity matched any of the recipients")
		}
		return nil, nil, nil, err
	}
	return sr, arFromEffective(ar, candidate), h, nil
}
func arFromEffective(ar *armorReader, candidate bool) *armorReader { if candidate { return ar }; return nil }

// lazyFileWriter opens file on first write
type lazyFileWriter struct { name string; f *os.File; err error; closed bool }
func (l *lazyFileWriter) Write(p []byte) (int, error) {
	if l.err != nil { return 0, l.err }
	if l.f == nil {
		f, err := os.Create(l.name); if err != nil { l.err = err; return 0, err }
		l.f = f
	}
	return l.f.Write(p)
}
func (l *lazyFileWriter) Close() error {
	if l.f != nil { return l.f.Close() }
	return l.err
}

// identity file CLI reader: returns identities or an error whose message is complete after "age: error: "
func readIdentityFileCLI(name string, tracker *stdinTracker, inputIsStdin bool) ([]identity, error) {
	var contents []byte
	if name == "-" {
		if inputIsStdin || (tracker != nil && tracker.used) {
			return nil, fmt.Errorf("reading %q: standard input is used for multiple purposes", name)
		}
		if tracker != nil { tracker.used = true; tracker.usedFor = "identities" }
		b, err := io.ReadAll(os.Stdin)
		if err != nil { return nil, fmt.Errorf("reading %q: failed to read %q: failed to read identities file: %w", name, name, err) }
		contents = b
	} else {
		f, err := os.Open(name)
		if err != nil { return nil, fmt.Errorf("reading %q: failed to open file: %w", name, err) }
		defer f.Close()
		b, err := io.ReadAll(f)
		if err != nil { return nil, fmt.Errorf("reading %q: failed to read %q: failed to read identities file: %w", name, name, err) }
		contents = b
	}
	// classify encrypted / armor
	lazy, usable, armorErr := classifyIdentityContents(name, contents)
	if armorErr != nil {
		return nil, fmt.Errorf("reading %q: %w", name, armorErr)
	}
	if lazy != nil { return []identity{lazy}, nil }
	contents = usable
	if bytes.HasPrefix(contents, []byte("-----BEGIN")) {
		ids, err := parseSSHIdentityFile(contents, name, nil, false)
		if err != nil { return nil, fmt.Errorf("reading %q: %w", name, err) }
		return ids, nil
	}
	ids, err := parseIdentityLines(contents)
	if err != nil { return nil, fmt.Errorf("reading %q: failed to read %q: %w", name, name, err) }
	return ids, nil
}

// convert identity to recipients for encryption
func identityToRecipients(id identity) ([]recipient, error) {
	switch v := id.(type) {
	case *x25519Identity:
		return []recipient{v.recipient()}, nil
	case *pqIdentity:
		r, err := v.recipient(); if err != nil { return nil, err }; return []recipient{r}, nil
	case *sshRSAIdentity:
		return []recipient{&sshRSARecipient{pub: &v.priv.PublicKey, blob: sshBlobRSA(&v.priv.PublicKey)}}, nil
	case *sshEdIdentity:
		pub := v.priv.Public().(interface{ Bytes() []byte })
		_ = pub
		edPub := v.priv.Public()
		// ed25519.PublicKey type assertion via helper in ssh_ed
		return []recipient{sshEdRecipientFromIdentity(v)}, nil
		_ = edPub
	case *pluginIdentity:
		return []recipient{&pluginRecipient{name: v.name, identityString: v.identityString, isIdentity: true, client: &pluginClient{name: v.name}}}, nil
	case *lazySSHIdentity:
		// recipient from public parts
		r, err := lazySSHToRecipient(v); if err != nil { return nil, err }; return []recipient{r}, nil
	case *encryptedIdentityFile:
		ids, err := v.decryptIdentities(); if err != nil { return nil, fmt.Errorf("internal error processing %q: %w", v.name, err) }
		var out []recipient
		for _, inner := range ids {
			rs, err := identityToRecipients(inner); if err != nil { return nil, err }; out = append(out, rs...)
		}
		return out, nil
	default:
		return nil, fmt.Errorf("internal error: unsupported identity type %T", id)
	}
}

func sshEdRecipientFromIdentity(v *sshEdIdentity) recipient {
	// defined in ssh_ed_identity.go
	return sshEdRecipientFromIdentityImpl(v)
}
func lazySSHToRecipient(v *lazySSHIdentity) (recipient, error) {
	// defined in ssh_lazy.go
	return lazySSHToRecipientImpl(v)
}

// passphrase encryption prompt
func getEncryptPassphrase() (string, error) {
	tty, shouldClose, err := terminalFile()
	if err != nil { return "", fmt.Errorf("could not read passphrase: %w", err) }
	if shouldClose { defer tty.Close() }
	pass, err := readPasswordFromTTY(tty, "Enter passphrase (leave empty to autogenerate a secure one): ")
	if err != nil { return "", fmt.Errorf("could not read passphrase: %w", err) }
	if pass == "" {
		generated := generatePassphrase()
		fmt.Fprintf(tty, "age: using autogenerated passphrase %q\n", generated)
		return generated, nil
	}
	confirm, err := readPasswordFromTTY(tty, "Confirm passphrase: ")
	if err != nil { return "", fmt.Errorf("could not read passphrase: %w", err) }
	if pass != confirm { return "", fmt.Errorf("passphrases didn't match") }
	return pass, nil
}

func isValidPluginName(s string) bool {
	if s == "" { return false }
	for i:=0;i<len(s);i++ {
		c := s[i]
		ok := (c>='a'&&c<='z')||(c>='A'&&c<='Z')||(c>='0'&&c<='9')|| c=='+'||c=='-'||c=='.'||c=='_'
		if !ok { return false }
	}
	return true
}
