func blowfishExpand0(c *blowfishCipher, data []byte) {
	j := 0
	for i := 0; i < 18; i++ {
		var v uint32
		for k := 0; k < 4; k++ { v = (v << 8) | uint32(data[j]); j = (j + 1) % len(data) }
		c.p[i] ^= v
	}
	var l, r uint32
	for i := 0; i < 18; i += 2 { l, r = blowfishEncrypt(c, l, r); c.p[i] = l; c.p[i+1] = r }
	for box := 0; box < 4; box++ {
		for i := 0; i < 256; i += 2 { l, r = blowfishEncrypt(c, l, r); c.s[box][i] = l; c.s[box][i+1] = r }
	}
}
