package main
func hpkeSealFromKEMSharedOpen(kemShared, info []byte, kemID uint16, ciphertext []byte) []byte {
	suiteCtx := append([]byte("HPKE"), byte(kemID>>8), byte(kemID), 0,1, 0,3)
	pskIDHash := labeledExtract(nil, suiteCtx, "psk_id_hash", []byte{})
	infoHash := labeledExtract(nil, suiteCtx, "info_hash", info)
	ksContext := append([]byte{0}, pskIDHash...); ksContext=append(ksContext, infoHash...)
	secret := labeledExtract(kemShared, suiteCtx, "secret", make([]byte,32))
	key := labeledExpand(secret, suiteCtx, "key", ksContext, 32)
	baseNonce := labeledExpand(secret, suiteCtx, "base_nonce", ksContext, 12)
	fk, err := aeadDecrypt(key, baseNonce, ciphertext, nil); if err!=nil { return nil }; return fk
}
