package main

import (
	"crypto/ecdh"
	"crypto/rand"
	"fmt"
)

func pqPublicFromSeed(seed []byte) ([]byte, error) {
	if len(seed) != 32 { return nil, fmt.Errorf("invalid MLKEM768-X25519 secret key") }
	exp := shake256(seed, 96)
	kp := mlkemGenerateKeyFromSeed(exp[:64])
	xp, err := ecdh.X25519().NewPrivateKey(exp[64:96]); if err != nil { return nil, err }
	return append(append([]byte{}, kp.ek...), xp.PublicKey().Bytes()...), nil
}

func pqDeriveShared(mlSS, xSS, ctX, pkX []byte) []byte {
	// X-Wing combiner with SHA3-256
	input := append(append(append(append(append([]byte{}, mlSS...), xSS...), ctX...), pkX...), []byte("\\.//^\\")...)
	ss := sha3_256(input)
	return ss[:]
}

func pqWrap(pub, fileKey []byte) (*stanza, error) {
	if len(pub) != 1216 { return nil, fmt.Errorf("invalid MLKEM768-X25519 public key") }
	mlPub := pub[:1184]; xPub := pub[1184:]
	m := make([]byte, 32); if _, err := rand.Read(m); err != nil { return nil, err }
	mlSS, ctML := mlkemEncapsulateDerand(mlPub, m)
	// X25519 ephemeral
	eph, err := ecdh.X25519().GenerateKey(rand.Reader); if err != nil { return nil, err }
	remote, err := ecdh.X25519().NewPublicKey(xPub); if err != nil { return nil, fmt.Errorf("failed to set up HPKE sender: %w", err) }
	xSS, err := eph.ECDH(remote); if err != nil { return nil, fmt.Errorf("failed to set up HPKE sender: %w", err) }
	ctX := eph.PublicKey().Bytes()
	enc := append(append([]byte{}, ctML...), ctX...)
	ss := pqDeriveShared(mlSS, xSS, ctX, xPub)
	wk := hkdfSHA256(ss, append(append([]byte{}, enc...), pub...), []byte("age-encryption.org/v1/mlkem768x25519"), 32)
	body := aeadEncrypt(wk, make([]byte, 12), fileKey, nil)
	return &stanza{Type: "mlkem768x25519", Args: []string{b64Encode(enc)}, Body: body}, nil
}

func pqUnwrap(seed []byte, stanzas []*stanza) ([]byte, error) {
	exp := shake256(seed, 96)
	kp := mlkemGenerateKeyFromSeed(exp[:64])
	xp, err := ecdh.X25519().NewPrivateKey(exp[64:96]); if err != nil { return nil, err }
	xPub := xp.PublicKey().Bytes()
	recipPub := append(append([]byte{}, kp.ek...), xPub...)
	for _, s := range stanzas {
		if s.Type != "mlkem768x25519" { continue }
		if len(s.Args) != 1 { return nil, fmt.Errorf("invalid mlkem768x25519 recipient block") }
		enc, err := b64Decode(s.Args[0]); if err != nil { return nil, fmt.Errorf("failed to parse mlkem768x25519 recipient: %w", err) }
		if len(enc) != 1120 { return nil, fmt.Errorf("invalid mlkem768x25519 recipient: invalid encapsulated key size") }
		if len(s.Body) != 32 { return nil, fmt.Errorf("encrypted value has unexpected length") }
		ctML := enc[:1088]; ctX := enc[1088:]
		remote, err := ecdh.X25519().NewPublicKey(ctX); if err != nil { return nil, fmt.Errorf("invalid mlkem768x25519 recipient: %w", err) }
		xSS, err := xp.ECDH(remote); if err != nil { return nil, fmt.Errorf("invalid mlkem768x25519 recipient: %w", err) }
		mlSS := mlkemDecapsulate(kp.dk, ctML)
		ss := pqDeriveShared(mlSS, xSS, ctX, xPub)
		wk := hkdfSHA256(ss, append(append([]byte{}, enc...), recipPub...), []byte("age-encryption.org/v1/mlkem768x25519"), 32)
		fk, err := aeadDecrypt(wk, make([]byte, 12), s.Body, nil)
		if err != nil { continue }
		if len(fk) != 16 { return nil, fmt.Errorf("encrypted value has unexpected length") }
		return fk, nil
	}
	return nil, errNoMatch
}

func p256TagWrap(pub, fileKey []byte) (*stanza, error) {
	// pub compressed 33
	uncomp, err := p256CompressedToUncompressed(pub); if err != nil { return nil, err }
	remote, err := ecdh.P256().NewPublicKey(uncomp); if err != nil { return nil, err }
	eph, err := ecdh.P256().GenerateKey(rand.Reader); if err != nil { return nil, err }
	shared, err := eph.ECDH(remote); if err != nil { return nil, err }
	share := eph.PublicKey().Bytes()
	// tag: first 4 bytes of SHA256(share || recipient uncompressed) as a plausible deterministic-per-ephemeral tag
	tagInput := append(append([]byte{}, share...), uncomp...)
	tag := sha256Sum(tagInput)
	wk := hkdfSHA256(shared, append(append([]byte{}, share...), uncomp...), []byte("age-encryption.org/v1/p256tag"), 32)
	body := aeadEncrypt(wk, make([]byte, 12), fileKey, nil)
	return &stanza{Type: "p256tag", Args: []string{b64Encode(tag[:4]), b64Encode(share)}, Body: body}, nil
}

func pqTagWrap(pub, fileKey []byte) (*stanza, error) {
	if len(pub) != 1249 { return nil, fmt.Errorf("invalid tagpq recipient public key: invalid public key size") }
	mlPub := pub[:1184]; p256Pub := pub[1184:]
	remote, err := ecdh.P256().NewPublicKey(p256Pub); if err != nil { return nil, fmt.Errorf("invalid tagpq recipient public key: %w", err) }
	m := make([]byte, 32); if _, err := rand.Read(m); err != nil { return nil, err }
	mlSS, ctML := mlkemEncapsulateDerand(mlPub, m)
	eph, err := ecdh.P256().GenerateKey(rand.Reader); if err != nil { return nil, err }
	sharedP, err := eph.ECDH(remote); if err != nil { return nil, err }
	share := eph.PublicKey().Bytes()
	enc := append(append([]byte{}, ctML...), share...)
	// combine mlSS and P256 shared analogous to XWing (using P256 ephemeral as ctX and recipient p256)
	ssInput := append(append(append(append(append([]byte{}, mlSS...), sharedP...), share...), p256Pub...), []byte("\\.//^\\")...)
	ss := sha3_256(ssInput)
	tag := sha256Sum(append(append([]byte{}, enc...), pub...))
	wk := hkdfSHA256(ss, append(append([]byte{}, enc...), pub...), []byte("age-encryption.org/v1/mlkem768p256tag"), 32)
	body := aeadEncrypt(wk, make([]byte, 12), fileKey, nil)
	return &stanza{Type: "mlkem768p256tag", Args: []string{b64Encode(tag[:4]), b64Encode(enc)}, Body: body}, nil
}
